PANEL_VARIANT=strict \
DID_DIR=repo_python/did_final_pyv2_paper_overlap \
bash run-py-2e-prepare-quality-did-input.sh

PANEL_VARIANT=strict \
DID_DIR=repo_python/did_final_pyv2_paper_overlap \
bash run-py-2f-did-borusyak-quality.sh

