    echo "Input:                         ${INPUT_FILE}"
    echo "Output:                        ${OUTPUT_FILE}"
    echo "Complete output:               ${COMPLETE_OUTPUT_FILE}"
    echo "QC output:                     ${QC_OUTPUT_FILE}"
    echo "Missing output:                ${MISSING_OUTPUT_FILE}"
