  echo "Completed:      $(date)"
  echo "Elapsed:        ${elapsed_text}"
  echo "Exit code:      ${status}"
  echo "Log file:       ${LOG_FILE}"
  echo "Main output:    ${OUTPUT_FILE}"
  echo "QC directory:   ${QC_DIR}"
  echo "============================================================"

  trap - EXIT
  exit "${status}"
}
