class ValidationRecorder:
    """Collect validation checks and fail after writing all diagnostics."""

    def __init__(self) -> None:
        self.checks: list[dict[str, Any]] = []
        self.errors: list[dict[str, Any]] = []

    def check(
        self,
        name: str,
        actual: Any,
        expected: Any,
        passed: bool,
        category: str,
        detail: str = "",
    ) -> None:
        self.checks.append(
            {
                "category": category,
                "check": name,
                "actual": actual,
                "expected": expected,
                "status": "PASS" if passed else "FAIL",
                "detail": detail,
            }
        )
        if not passed:
            self.errors.append(
                {
                    "category": category,
                    "check": name,
                    "actual": actual,
                    "expected": expected,
                    "detail": detail,
                }
            )

    def require_zero(
        self,
        name: str,
        actual: int,
        category: str,
        detail: str = "",
    ) -> None:
        self.check(name, int(actual), 0, int(actual) == 0, category, detail)

    def require_equal(
        self,
        name: str,
        actual: Any,
        expected: Any,
        category: str,
        detail: str = "",
    ) -> None:
        self.check(name, actual, expected, actual == expected, category, detail)



