        "issues",
        "age",
        "ncloc_paper",
        "ncloc_python_snapshot",
        "paper_covariate_matched",
        "python_snapshot_ncloc_matched",
        "analysis_ready_agc_paper_ncloc",
        "analysis_ready_agc_python_snapshot_ncloc",
        "python_file_count",
        "files_analyzed",
        "failure_count",
        "agc_repo_month_matched",
    ] + LEAD_COLS + LAG_COLS
    for columns in COUNT_GROUPS.values():
        numeric_columns.extend(columns)
    to_numeric(df, numeric_columns)

    recorder.require_equal("panel_rows", len(df), args.expected_rows, "dimensions")
    recorder.require_equal(
        "panel_repositories",
        int(df["repo_name"].nunique()),
        args.expected_repositories,
        "dimensions",
    )
    recorder.require_zero(
        "duplicate_repo_time_source_keys",
        int(df.duplicated(KEY_COLS).sum()),
        "keys",
    )

    invalid_sources = sorted(set(df["dataset_source"]) - ALLOWED_SOURCES)
    recorder.require_equal("invalid_dataset_sources", invalid_sources, [], "keys")

    treatment = df["dataset_source"].eq("treatment")
    control = df["dataset_source"].eq("control")
    recorder.require_equal(
        "treatment_rows", int(treatment.sum()), args.expected_treatment_rows, "dimensions"
    )
    recorder.require_equal(
        "control_rows", int(control.sum()), args.expected_control_rows, "dimensions"
    )
    recorder.require_equal(
        "treatment_repositories",
        int(df.loc[treatment, "repo_name"].nunique()),
        args.expected_treatment_repositories,
        "dimensions",
    )
    recorder.require_equal(
        "control_repositories",
        int(df.loc[control, "repo_name"].nunique()),
        args.expected_control_repositories,
        "dimensions",
    )
    recorder.require_equal(
        "post_event_rows",
        int(df["post_event"].fillna(0).sum()),
        args.expected_post_rows,
        "event",
    )
    recorder.require_equal("min_time", df["time"].min(), args.expected_min_time, "dates")
    recorder.require_equal("max_time", df["time"].max(), args.expected_max_time, "dates")

    invalid_binary_columns = [
        "is_treatment",
        "post_event",
        "cursor",
        "paper_covariate_matched",
        "python_snapshot_ncloc_matched",
        "analysis_ready_agc_paper_ncloc",
        "analysis_ready_agc_python_snapshot_ncloc",
        "agc_repo_month_matched",
    ] + LEAD_COLS + LAG_COLS
    for column in invalid_binary_columns:
        invalid_count = int((~df[column].isin([0, 1])).sum())
        recorder.require_zero(f"invalid_binary_{column}", invalid_count, "types")

    recorder.require_zero(
        "is_treatment_post_event_mismatches",
        int(df["is_treatment"].ne(df["post_event"]).sum()),
        "event",
    )
    recorder.require_zero(
        "control_post_event_nonzero",
        int((control & df["post_event"].ne(0)).sum()),
        "event",
    )
    recorder.require_zero(
        "control_is_treatment_nonzero",
        int((control & df["is_treatment"].ne(0)).sum()),
        "event",
    )
    recorder.require_zero(
        "control_event_nonmissing",
        int((control & df["event"].notna()).sum()),
        "event",
    )
    recorder.require_zero(
        "control_time_to_event_nonmissing",
        int((control & df["time_to_event"].notna()).sum()),
        "event",
    )
    recorder.require_zero(
        "treatment_event_missing",
        int((treatment & df["event"].isna()).sum()),
        "event",
    )
    recorder.require_zero(
        "treatment_time_to_event_missing",
        int((treatment & df["time_to_event"].isna()).sum()),
        "event",
    )

    treatment_rows = df.loc[treatment].copy()
    recomputed_time_to_event = month_difference(
        treatment_rows["time"], treatment_rows["event"]
    )
    observed_time_to_event = treatment_rows["time_to_event"].astype("int64")
    recorder.require_zero(
        "treatment_time_to_event_mismatches",
        int(observed_time_to_event.ne(recomputed_time_to_event).sum()),
        "event",
    )

    expected_post = treatment_rows["time_to_event"].ge(0).astype(int)
    recorder.require_zero(
        "treatment_absorbing_post_mismatches",
        int(treatment_rows["post_event"].astype(int).ne(expected_post).sum()),
        "event",
    )

    for value in range(1, 6):
        expected = treatment_rows["time_to_event"].eq(-value).astype(int)
        recorder.require_zero(
            f"lead_{value}_mismatches",
            int(treatment_rows[f"lead_{value}"].astype(int).ne(expected).sum()),
            "lead_lag",
        )
    expected_lead_6 = treatment_rows["time_to_event"].le(-6).astype(int)
    recorder.require_zero(
        "lead_6_mismatches",
        int(treatment_rows["lead_6"].astype(int).ne(expected_lead_6).sum()),
        "lead_lag",
    )

    for value in range(0, 6):
        expected = treatment_rows["time_to_event"].eq(value).astype(int)
        recorder.require_zero(
            f"lag_{value}_mismatches",
            int(treatment_rows[f"lag_{value}"].astype(int).ne(expected).sum()),
            "lead_lag",
        )
    expected_lag_6 = treatment_rows["time_to_event"].ge(6).astype(int)
    recorder.require_zero(
        "lag_6_mismatches",
        int(treatment_rows["lag_6"].astype(int).ne(expected_lag_6).sum()),
        "lead_lag",
    )
    recorder.require_zero(
        "control_nonzero_lead_lag_values",
        int(df.loc[control, LEAD_COLS + LAG_COLS].fillna(0).ne(0).sum().sum()),
        "lead_lag",
    )

    integer_count_columns = [
        "python_file_count",
        "files_analyzed",
        "failure_count",
    ] + [
        column
        for group_columns in COUNT_GROUPS.values()
        for column in group_columns[:3]
    ]
    for column in integer_count_columns:
        values = df[column]
        invalid = values.notna() & (
            ~np.isfinite(values) | values.lt(0) | values.mod(1).ne(0)
        )
        recorder.require_zero(
            f"invalid_nonnegative_integer_{column}", int(invalid.sum()), "counts"
        )

    matched = df["agc_repo_month_matched"].eq(1)
    recorder.require_equal(
        "agc_repo_month_matched_rows",
        int(matched.sum()),
        args.expected_rows,
        "coverage",
    )
    recorder.require_zero(
        "agc_failure_count_sum",
        int(df["failure_count"].fillna(0).sum()),
        "coverage",
    )
    recorder.require_zero(
        "missing_agc_analysis_status",
        int(df["agc_analysis_status"].isna().sum()),
        "coverage",
    )
    recorder.require_zero(
        "missing_agc_repo_month_status_rows",
        int(df["agc_analysis_status"].astype(str).eq("missing_agc_repo_month").sum()),
        "coverage",
    )

    partition_checks = {
        "top_level_function_plus_class": df["top_level_blocks_scored"].ne(
            df["function_blocks_scored"] + df["class_blocks_scored"]
        ),
        "top_level_agc_function_plus_class": df["agc_top_level_blocks"].ne(
            df["agc_function_blocks"] + df["agc_class_blocks"]
        ),
        "top_level_human_function_plus_class": df["human_top_level_blocks"].ne(
            df["human_function_blocks"] + df["human_class_blocks"]
        ),
    }
    for label, mismatch in partition_checks.items():
        recorder.require_zero(label, int((matched & mismatch).sum()), "counts")

    coverage_rows: list[dict[str, Any]] = []
    expected_nonmissing = {
        "top_level": args.expected_top_level_nonmissing,
        "function": args.expected_function_nonmissing,
        "class": args.expected_class_nonmissing,
    }
    for label, (total_col, agc_col, human_col, ratio_col) in COUNT_GROUPS.items():
        partition_mismatch = matched & df[total_col].ne(df[agc_col] + df[human_col])
        recorder.require_zero(
            f"{label}_agc_human_partition_mismatches",
            int(partition_mismatch.sum()),
            "counts",
        )

        denominator_positive = df[total_col].gt(0)
        ratio_missing = df[ratio_col].isna()
        recorder.require_zero(
            f"{label}_ratio_missing_with_positive_denominator",
            int((matched & denominator_positive & ratio_missing).sum()),
            "ratios",
        )
        recorder.require_zero(
            f"{label}_ratio_nonmissing_with_zero_denominator",
            int((matched & df[total_col].eq(0) & df[ratio_col].notna()).sum()),
            "ratios",
        )

        observed_ratio = df.loc[matched & denominator_positive, ratio_col]
        expected_ratio = (
            df.loc[matched & denominator_positive, agc_col]
            / df.loc[matched & denominator_positive, total_col]
        )
        ratio_mismatch = ~np.isclose(
            observed_ratio,
            expected_ratio,
            rtol=1e-12,
            atol=1e-12,
            equal_nan=True,
        )
        recorder.require_zero(
            f"{label}_ratio_value_mismatches",
            int(ratio_mismatch.sum()),
            "ratios",
        )
        invalid_range = df[ratio_col].notna() & ~df[ratio_col].between(0, 1)
        recorder.require_zero(
            f"{label}_ratio_outside_unit_interval",
            int(invalid_range.sum()),
            "ratios",
        )

        nonmissing = int(df[ratio_col].notna().sum())
        recorder.require_equal(
            f"{label}_ratio_nonmissing",
            nonmissing,
            expected_nonmissing[label],
            "coverage",
        )
        coverage_rows.append(
            {
                "outcome": ratio_col,
                "rows": len(df),
                "nonmissing": nonmissing,
                "missing": int(df[ratio_col].isna().sum()),
                "zero_denominator": int(df[total_col].eq(0).sum()),
                "mean": df[ratio_col].mean(),
                "median": df[ratio_col].median(),
            }
        )

    for column in [
        "commits",
        "lines_added",
        "lines_removed",
        "contributors",
        "stars",
        "issues",
        "age",
        "ncloc_paper",
        "ncloc_python_snapshot",
    ]:
        recorder.require_zero(
            f"invalid_finite_nonnegative_{column}",
            finite_nonnegative_count(df[column]),
            "covariates",
        )

    recorder.require_equal(
        "python_snapshot_ncloc_matched_rows",
        int(df["python_snapshot_ncloc_matched"].sum()),
        args.expected_rows,
        "ncloc",
    )
    recorder.require_equal(
        "ncloc_python_snapshot_nonmissing",
        int(df["ncloc_python_snapshot"].notna().sum()),
        args.expected_rows,
        "ncloc",
    )

    expected_paper_ready = (
        matched
        & df["agc_top_level_block_ratio"].notna()
        & df[["stars", "issues", "age", "ncloc_paper"]].notna().all(axis=1)
    ).astype(int)
    expected_snapshot_ready = (
        matched
        & df["agc_top_level_block_ratio"].notna()
        & df[["stars", "issues", "age", "ncloc_python_snapshot"]]
        .notna()
        .all(axis=1)
        & df["python_snapshot_ncloc_matched"].eq(1)
    ).astype(int)

    recorder.require_zero(
        "paper_ncloc_readiness_flag_mismatches",
        int(
            df["analysis_ready_agc_paper_ncloc"]
            .astype(int)
            .ne(expected_paper_ready)
            .sum()
        ),
        "readiness",
    )
    recorder.require_zero(
        "snapshot_ncloc_readiness_flag_mismatches",
        int(
            df["analysis_ready_agc_python_snapshot_ncloc"]
            .astype(int)
            .ne(expected_snapshot_ready)
            .sum()
        ),
        "readiness",
    )
    recorder.require_equal(
        "paper_ncloc_ready_rows",
        int(df["analysis_ready_agc_paper_ncloc"].sum()),
        args.expected_paper_ready_rows,
        "readiness",
    )
    recorder.require_equal(
        "snapshot_ncloc_ready_rows",
        int(df["analysis_ready_agc_python_snapshot_ncloc"].sum()),
        args.expected_snapshot_ready_rows,
        "readiness",
    )

    by_source = (
        df.groupby("dataset_source", as_index=False)
        .agg(
            rows=("repo_name", "size"),
            repositories=("repo_name", "nunique"),
            post_rows=("post_event", "sum"),
            top_level_nonmissing=("agc_top_level_block_ratio", "count"),
            function_nonmissing=("agc_function_block_ratio", "count"),
            class_nonmissing=("agc_class_block_ratio", "count"),
            paper_ncloc_nonmissing=("ncloc_paper", "count"),
            snapshot_ncloc_nonmissing=("ncloc_python_snapshot", "count"),
            paper_ready_rows=("analysis_ready_agc_paper_ncloc", "sum"),
            snapshot_ready_rows=("analysis_ready_agc_python_snapshot_ncloc", "sum"),
        )
    )
    return by_source, pd.DataFrame(coverage_rows)



def validate_commit_ncloc(
    df: pd.DataFrame,
    args: argparse.Namespace,
    recorder: ValidationRecorder,
) -> pd.DataFrame:
    """Validate repository-commit Python snapshot NCLOC output."""
    require_columns(df, COMMIT_NCLOC_REQUIRED_COLUMNS, "repository-commit NCLOC")
    df = df.copy()
    for column in COMMIT_KEY_COLS:
        df[column] = df[column].astype(str).str.strip()

    numeric_columns = [
        "python_files_manifest",
        "regular_python_files_counted",
        "symlinks_skipped",
        "total_physical_lines",
        "comment_only_lines",
        "ncloc_python_snapshot",
        "tokenized_files",
        "fallback_files",
        "ncloc_failure_count",
    ]
    to_numeric(df, numeric_columns)

    recorder.require_equal(
        "repo_commit_ncloc_rows", len(df), args.expected_commit_rows, "commit_ncloc"
    )
    recorder.require_zero(
        "repo_commit_ncloc_duplicate_keys",
        int(df.duplicated(COMMIT_KEY_COLS).sum()),
        "commit_ncloc",
    )
    invalid_sources = sorted(set(df["dataset_source"]) - ALLOWED_SOURCES)
    recorder.require_equal(
        "repo_commit_ncloc_invalid_sources", invalid_sources, [], "commit_ncloc"
    )

    for column in numeric_columns:
        invalid = df[column].isna() | (
            ~np.isfinite(df[column]) | df[column].lt(0) | df[column].mod(1).ne(0)
        )
        recorder.require_zero(
            f"repo_commit_invalid_{column}", int(invalid.sum()), "commit_ncloc"
        )

    recorder.require_zero(
        "repo_commit_ncloc_failure_count_sum",
        int(df["ncloc_failure_count"].sum()),
        "commit_ncloc",
    )
    recorder.require_zero(
        "repo_commit_file_manifest_count_mismatches",
        int(
            df["python_files_manifest"]
            .ne(df["regular_python_files_counted"] + df["symlinks_skipped"])
            .sum()
        ),
        "commit_ncloc",
    )
    recorder.require_zero(
        "repo_commit_tokenizer_fallback_count_mismatches",
        int(
            df["regular_python_files_counted"]
            .ne(df["tokenized_files"] + df["fallback_files"])
            .sum()
        ),
        "commit_ncloc",
    )
    recorder.require_zero(
        "repo_commit_physical_line_lower_bound_violations",
        int(
            df["total_physical_lines"]
            .lt(df["ncloc_python_snapshot"] + df["comment_only_lines"])
            .sum()
        ),
        "commit_ncloc",
    )

    summary = (
        df.groupby("dataset_source", as_index=False)
        .agg(
            unique_commits=("repo_name", "size"),
            repositories=("repo_name", "nunique"),
            regular_python_files_counted=("regular_python_files_counted", "sum"),
            tokenized_files=("tokenized_files", "sum"),
            fallback_files=("fallback_files", "sum"),
            ncloc_failure_count=("ncloc_failure_count", "sum"),
            ncloc_python_snapshot_sum=("ncloc_python_snapshot", "sum"),
        )
    )
    all_row = pd.DataFrame(
        [
            {
                "dataset_source": "all",
                "unique_commits": len(df),
                "repositories": int(df["repo_name"].nunique()),
                "regular_python_files_counted": int(
                    df["regular_python_files_counted"].sum()
                ),
                "tokenized_files": int(df["tokenized_files"].sum()),
                "fallback_files": int(df["fallback_files"].sum()),
                "ncloc_failure_count": int(df["ncloc_failure_count"].sum()),
                "ncloc_python_snapshot_sum": int(
                    df["ncloc_python_snapshot"].sum()
                ),
            }
        ]
    )
    return pd.concat([summary, all_row], ignore_index=True)



def validate_repo_month_outcomes(
    main: pd.DataFrame,
    outcomes: pd.DataFrame,
    args: argparse.Namespace,
    recorder: ValidationRecorder,
) -> None:
    """Validate the repository-month outcome artifact and exact main-panel overlap."""
    required = KEY_COLS + [
        "latest_commit",
        "python_file_count",
        "files_analyzed",
        "failure_count",
        "agc_analysis_status",
        "ncloc_python_snapshot",
        "python_snapshot_ncloc_matched",
    ] + [column for columns in COUNT_GROUPS.values() for column in columns]
    require_columns(outcomes, required, "repository-month AGC outcomes")
    outcomes = outcomes.copy()
    outcomes["time"] = outcomes["time"].astype(str).str.slice(0, 7)
    outcomes["repo_name"] = outcomes["repo_name"].astype(str).str.strip()
    outcomes["dataset_source"] = outcomes["dataset_source"].astype(str).str.strip()

    recorder.require_equal(
        "repo_month_outcome_rows",
        len(outcomes),
        args.expected_repo_month_outcome_rows,
        "repo_month_outcomes",
    )
    recorder.require_zero(
        "repo_month_outcome_duplicate_keys",
        int(outcomes.duplicated(KEY_COLS).sum()),
        "repo_month_outcomes",
    )

    compare_columns = [
        "latest_commit",
        "python_file_count",
        "files_analyzed",
        "failure_count",
        "agc_analysis_status",
        "ncloc_python_snapshot",
        "python_snapshot_ncloc_matched",
    ] + [column for columns in COUNT_GROUPS.values() for column in columns]
    left = main[KEY_COLS + compare_columns].copy()
    right = outcomes[KEY_COLS + compare_columns].copy()
    merged = left.merge(
        right,
        on=KEY_COLS,
        how="left",
        validate="one_to_one",
        suffixes=("_main", "_outcome"),
        indicator=True,
    )
    recorder.require_zero(
        "main_rows_missing_from_repo_month_outcomes",
        int(merged["_merge"].ne("both").sum()),
        "repo_month_outcomes",
    )

    mismatch_count = 0
    for column in compare_columns:
        left_col = merged[f"{column}_main"]
        right_col = merged[f"{column}_outcome"]
        if column in {"latest_commit", "agc_analysis_status"}:
            mismatch = left_col.fillna("<NA>").astype(str).ne(
                right_col.fillna("<NA>").astype(str)
            )
        elif column.endswith("_ratio") or column == "ncloc_python_snapshot":
            mismatch = ~np.isclose(
                pd.to_numeric(left_col, errors="coerce"),
                pd.to_numeric(right_col, errors="coerce"),
                rtol=1e-12,
                atol=1e-12,
                equal_nan=True,
            )
        else:
            mismatch = pd.to_numeric(left_col, errors="coerce").fillna(-1).ne(
                pd.to_numeric(right_col, errors="coerce").fillna(-1)
            )
        mismatch_count += int(mismatch.sum())
    recorder.require_zero(
        "main_repo_month_outcome_value_mismatches",
        mismatch_count,
        "repo_month_outcomes",
    )



def validate_detector_provenance(
    args: argparse.Namespace,
    recorder: ValidationRecorder,
) -> pd.DataFrame:
    """Validate treatment/control detector provenance and saved comparison QC."""
    combined = load_json(args.combined_validation, "combined detector validation")
    recorder.require_equal(
        "combined_detector_status", combined.get("status"), "PASS", "detector"
    )
    recorder.require_equal(
        "combined_detector_metadata_errors",
        combined.get("metadata_comparison_errors", []),
        [],
        "detector",
    )
    recorder.require_equal(
        "combined_detector_errors", combined.get("errors", []), [], "detector"
    )

    treatment = load_json(args.run_metadata_treatment, "treatment run metadata")
    control = load_json(args.run_metadata_control, "control run metadata")
    rows: list[dict[str, Any]] = []
    for field in METADATA_COMPARE_FIELDS:
        treatment_value = treatment.get(field)
        control_value = control.get(field)
        matches = treatment_value == control_value
        recorder.require_equal(
            f"detector_metadata_match_{field}",
            int(matches),
            1,
            "detector",
            detail=f"treatment={treatment_value!r}; control={control_value!r}",
        )
        rows.append(
            {
                "field": field,
                "treatment_value": treatment_value,
                "control_value": control_value,
                "matches": int(matches),
            }
        )

    expected_values = {
        "experiment": args.expected_experiment,
        "classifier": args.expected_classifier,
        "representation": args.expected_representation,
        "expected_score_mode": args.expected_score_mode,
        "model_key": args.expected_model_key,
    }
    for field, expected in expected_values.items():
        recorder.require_equal(
            f"expected_detector_{field}",
            treatment.get(field),
            expected,
            "detector",
        )

    qc_path = args.prepare_qc_dir / "agc_detector_metadata_comparison.csv"
    require_file(qc_path, "run-py-3b detector metadata comparison")
    qc = pd.read_csv(qc_path, low_memory=False)
    require_columns(
        qc,
        ["field", "treatment_value", "control_value", "matches"],
        "run-py-3b detector metadata comparison",
    )
    recorder.require_equal(
        "detector_metadata_qc_rows",
        len(qc),
        len(METADATA_COMPARE_FIELDS),
        "detector",
    )
    recorder.require_zero(
        "detector_metadata_qc_mismatches",
        int(pd.to_numeric(qc["matches"], errors="coerce").fillna(0).ne(1).sum()),
        "detector",
    )
    return pd.DataFrame(rows)



def validate_prepare_qc_files(
    args: argparse.Namespace,
    recorder: ValidationRecorder,
) -> pd.DataFrame:
    """Validate required run-py-3b mismatch/error files are header-only."""
    rows: list[dict[str, Any]] = []
    for filename in EMPTY_QC_FILENAMES:
        path = args.prepare_qc_dir / filename
        require_file(path, f"run-py-3b QC file {filename}")
        frame = pd.read_csv(path, low_memory=False)
        data_rows = len(frame)
        recorder.require_zero(
            f"empty_qc_{filename}",
            data_rows,
            "prepare_qc",
            detail=str(path),
        )
        rows.append(
            {
                "file": filename,
                "path": str(path),
                "data_rows": data_rows,
                "status": "PASS" if data_rows == 0 else "FAIL",
            }
        )

    qc_summary_path = args.prepare_qc_dir / "agc_did_input_qc.csv"
    require_file(qc_summary_path, "run-py-3b QC summary")
    summary = pd.read_csv(qc_summary_path, low_memory=False)
    require_columns(summary, ["check", "value"], "run-py-3b QC summary")
    summary_map = dict(zip(summary["check"].astype(str), summary["value"]))
    expected_checks = {
        "base_rows": args.expected_rows,
        "output_rows": args.expected_rows,
        "row_count_preserved": 1,
        "base_repositories": args.expected_repositories,
        "matched_base_rows": args.expected_rows,
        "unmatched_base_rows": 0,
        "duplicate_output_keys": 0,
        "treatment_rows": args.expected_treatment_rows,
        "control_rows": args.expected_control_rows,
        "agc_failure_count_sum": 0,
        "python_snapshot_ncloc_matched_rows": args.expected_rows,
        "analysis_ready_agc_paper_ncloc_rows": args.expected_paper_ready_rows,
        "analysis_ready_agc_python_snapshot_ncloc_rows": args.expected_snapshot_ready_rows,
    }
    for check, expected in expected_checks.items():
        actual_raw = summary_map.get(check)
        actual = pd.to_numeric(pd.Series([actual_raw]), errors="coerce").iloc[0]
        actual_value = int(actual) if pd.notna(actual) else None
        recorder.require_equal(
            f"prepare_qc_summary_{check}", actual_value, expected, "prepare_qc"
        )
    return pd.DataFrame(rows)



def decode_python_source(data: bytes) -> str:
    """Decode Python source using its declared source encoding."""
    reader = io.BytesIO(data).readline
    encoding, _ = tokenize.detect_encoding(reader)
    return data.decode(encoding)


def tokenizer_fallback_reason(data: bytes) -> str | None:
    """Return the tokenizer exception when the fallback rule is required."""
    text = decode_python_source(data)
    try:
        list(tokenize.generate_tokens(io.StringIO(text).readline))
    except (tokenize.TokenError, IndentationError, SyntaxError) as exc:
        return f"{type(exc).__name__}: {exc}"
    return None


def fallback_line_metrics(data: bytes) -> dict[str, int]:
    """Compute the exact physical-line fallback metrics used by run-py-3b."""
    text = decode_python_source(data)
    lines = text.splitlines()
    blank_lines = sum(1 for line in lines if not line.strip())
    comment_only_lines = sum(
        1 for line in lines if line.strip() and line.lstrip().startswith("#")
    )
    fallback_ncloc = len(lines) - blank_lines - comment_only_lines
    return {
        "size_bytes_observed": len(data),
        "physical_lines": len(lines),
        "blank_lines": blank_lines,
        "comment_only_lines": comment_only_lines,
        "fallback_ncloc": fallback_ncloc,
    }


def safe_ratio(numerator: float, denominator: float) -> float:
    """Return a ratio or NaN when the denominator is zero."""
    if denominator == 0:
        return float("nan")
    return float(numerator) / float(denominator)


def audit_fallback_files(
    commit_ncloc: pd.DataFrame,
    snapshot_root: Path,
    recorder: ValidationRecorder,
) -> pd.DataFrame:
    """Locate exact files that required the Python tokenizer fallback rule."""
    if not snapshot_root.is_dir():
        raise FileNotFoundError(f"snapshot root not found: {snapshot_root}")

    candidate_commits = commit_ncloc.loc[
        pd.to_numeric(commit_ncloc["fallback_files"], errors="coerce").fillna(0).gt(0)
    ].copy()
    audit_rows: list[dict[str, Any]] = []

    for row in candidate_commits.itertuples(index=False):
        source = str(row.dataset_source)
        repo_name = str(row.repo_name)
        commit = str(row.latest_commit)
        repo_slug = repo_name.replace("/", "_")
        snapshot_dir = snapshot_root / source / repo_slug / commit
        manifest_path = snapshot_dir / "_files.jsonl"
        require_file(manifest_path, "snapshot file manifest for fallback audit")

        with manifest_path.open("r", encoding="utf-8") as handle:
            for line_number, line in enumerate(handle, start=1):
                if not line.strip():
                    continue
                record = json.loads(line)
                if str(record.get("file_type", "")) != "file":
                    continue
                relative_path = str(record["relative_path"])
                source_path = snapshot_dir / relative_path
                data = source_path.read_bytes()
                reason = tokenizer_fallback_reason(data)
                if reason is None:
                    continue
                audit_rows.append(
                    {
                        "dataset_source": source,
                        "repo_name": repo_name,
                        "latest_commit": commit,
                        "relative_path": relative_path,
                        "snapshot_path": str(source_path),
                        "manifest_line": line_number,
                        "content_sha256": record.get("content_sha256", ""),
                        "size_bytes_manifest": record.get("size_bytes"),
                        "fallback_reason": reason,
                    }
                )

    audit = pd.DataFrame(
        audit_rows,
        columns=[
            "dataset_source",
            "repo_name",
            "latest_commit",
            "relative_path",
            "snapshot_path",
            "manifest_line",
            "content_sha256",
            "size_bytes_manifest",
            "fallback_reason",
        ],
    )
    expected_total = int(
        pd.to_numeric(commit_ncloc["fallback_files"], errors="coerce").fillna(0).sum()
    )
    recorder.require_equal(
        "fallback_file_audit_count", len(audit), expected_total, "fallback_audit"
    )

    if not audit.empty:
        expected_by_commit = (
            commit_ncloc.loc[
                pd.to_numeric(commit_ncloc["fallback_files"], errors="coerce")
                .fillna(0)
                .gt(0),
                COMMIT_KEY_COLS + ["fallback_files"],
            ]
            .copy()
        )
        observed_by_commit = (
            audit.groupby(COMMIT_KEY_COLS, as_index=False)
            .size()
            .rename(columns={"size": "observed_fallback_files"})
        )
        checked = expected_by_commit.merge(
            observed_by_commit,
            on=COMMIT_KEY_COLS,
            how="left",
            validate="one_to_one",
        )
        checked["observed_fallback_files"] = checked[
            "observed_fallback_files"
        ].fillna(0)
        recorder.require_zero(
            "fallback_file_audit_commit_count_mismatches",
            int(
                pd.to_numeric(checked["fallback_files"], errors="coerce")
                .ne(pd.to_numeric(checked["observed_fallback_files"], errors="coerce"))
                .sum()
            ),
            "fallback_audit",
        )
    return audit


def build_fallback_impact_outputs(
    fallback_audit: pd.DataFrame,
    commit_ncloc: pd.DataFrame,
    main_panel: pd.DataFrame,
    recorder: ValidationRecorder,
) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """Quantify fallback line-volume impact without modifying the main panel."""
    detail_columns = [
        "dataset_source",
        "repo_name",
        "latest_commit",
        "relative_path",
        "snapshot_path",
        "manifest_line",
        "content_sha256",
        "size_bytes_manifest",
        "size_bytes_observed",
        "error_type",
        "fallback_reason",
        "physical_lines",
        "blank_lines",
        "comment_only_lines",
        "fallback_ncloc",
        "logical_file_key",
        "logical_file_occurrences",
        "logical_file_unique_contents",
    ]
    if fallback_audit.empty:
        details = pd.DataFrame(columns=detail_columns)
    else:
        detail_rows: list[dict[str, Any]] = []
        for row in fallback_audit.itertuples(index=False):
            source_path = Path(str(row.snapshot_path))
            require_file(source_path, "fallback source file")
            data = source_path.read_bytes()
            metrics = fallback_line_metrics(data)
            detail_rows.append(
                {
                    "dataset_source": str(row.dataset_source),
                    "repo_name": str(row.repo_name),
                    "latest_commit": str(row.latest_commit),
                    "relative_path": str(row.relative_path),
                    "snapshot_path": str(row.snapshot_path),
                    "manifest_line": int(row.manifest_line),
                    "content_sha256": str(getattr(row, "content_sha256", "") or ""),
                    "size_bytes_manifest": getattr(row, "size_bytes_manifest", np.nan),
                    "size_bytes_observed": metrics["size_bytes_observed"],
                    "error_type": str(row.fallback_reason).split(":", 1)[0],
                    "fallback_reason": str(row.fallback_reason),
                    "physical_lines": metrics["physical_lines"],
                    "blank_lines": metrics["blank_lines"],
                    "comment_only_lines": metrics["comment_only_lines"],
                    "fallback_ncloc": metrics["fallback_ncloc"],
                    "logical_file_key": f"{row.repo_name}::{row.relative_path}",
                }
            )
        details = pd.DataFrame(detail_rows)
        details["logical_file_occurrences"] = details.groupby(
            "logical_file_key"
        )["logical_file_key"].transform("size")
        details["logical_file_unique_contents"] = details.groupby(
            "logical_file_key"
        )["content_sha256"].transform(lambda values: values.loc[values.ne("")].nunique())
        details = details[detail_columns].sort_values(
            COMMIT_KEY_COLS + ["relative_path"], kind="stable"
        ).reset_index(drop=True)

    recorder.require_equal(
        "fallback_impact_detail_rows",
        len(details),
        len(fallback_audit),
        "fallback_impact",
    )
    if not details.empty:
        arithmetic_mismatch = details["physical_lines"].ne(
            details["blank_lines"]
            + details["comment_only_lines"]
            + details["fallback_ncloc"]
        )
        recorder.require_zero(
            "fallback_impact_line_arithmetic_mismatches",
            int(arithmetic_mismatch.sum()),
            "fallback_impact",
        )
        recorder.require_zero(
            "fallback_impact_negative_ncloc_rows",
            int(pd.to_numeric(details["fallback_ncloc"], errors="coerce").lt(0).sum()),
            "fallback_impact",
        )
        manifest_sizes = pd.to_numeric(details["size_bytes_manifest"], errors="coerce")
        observed_sizes = pd.to_numeric(details["size_bytes_observed"], errors="coerce")
        size_mismatch = manifest_sizes.notna() & manifest_sizes.ne(observed_sizes)
        recorder.require_zero(
            "fallback_impact_manifest_size_mismatches",
            int(size_mismatch.sum()),
            "fallback_impact",
        )

    commit_totals = (
        details.groupby(COMMIT_KEY_COLS, as_index=False)
        .agg(
            fallback_file_occurrences=("relative_path", "size"),
            fallback_unique_logical_paths=("logical_file_key", "nunique"),
            fallback_physical_lines=("physical_lines", "sum"),
            fallback_blank_lines=("blank_lines", "sum"),
            fallback_comment_only_lines=("comment_only_lines", "sum"),
            fallback_ncloc=("fallback_ncloc", "sum"),
        )
        if not details.empty
        else pd.DataFrame(
            columns=COMMIT_KEY_COLS
            + [
                "fallback_file_occurrences",
                "fallback_unique_logical_paths",
                "fallback_physical_lines",
                "fallback_blank_lines",
                "fallback_comment_only_lines",
                "fallback_ncloc",
            ]
        )
    )
    commit_reference = commit_ncloc[
        COMMIT_KEY_COLS
        + [
            "regular_python_files_counted",
            "ncloc_python_snapshot",
            "fallback_files",
        ]
    ].copy()
    by_commit = commit_totals.merge(
        commit_reference,
        on=COMMIT_KEY_COLS,
        how="left",
        validate="one_to_one",
    )
    if not by_commit.empty:
        for column in [
            "fallback_file_occurrences",
            "fallback_ncloc",
            "ncloc_python_snapshot",
            "fallback_files",
        ]:
            by_commit[column] = pd.to_numeric(by_commit[column], errors="coerce")
        by_commit["ncloc_python_snapshot_excluding_fallback"] = (
            by_commit["ncloc_python_snapshot"] - by_commit["fallback_ncloc"]
        )
        by_commit["fallback_ncloc_share"] = np.where(
            by_commit["ncloc_python_snapshot"].gt(0),
            by_commit["fallback_ncloc"] / by_commit["ncloc_python_snapshot"],
            np.nan,
        )
        recorder.require_zero(
            "fallback_impact_commit_file_count_mismatches",
            int(
                by_commit["fallback_file_occurrences"]
                .ne(by_commit["fallback_files"])
                .sum()
            ),
            "fallback_impact",
        )
        recorder.require_zero(
            "fallback_impact_commit_ncloc_exceeds_total",
            int(by_commit["fallback_ncloc"].gt(by_commit["ncloc_python_snapshot"]).sum()),
            "fallback_impact",
        )
        recorder.require_zero(
            "fallback_impact_negative_excluding_fallback_ncloc",
            int(
                by_commit["ncloc_python_snapshot_excluding_fallback"].lt(0).sum()
            ),
            "fallback_impact",
        )

    main_for_impact = main_panel[
        KEY_COLS + ["latest_commit", "ncloc_python_snapshot"]
    ].copy()
    main_for_impact["latest_commit"] = main_for_impact["latest_commit"].astype(str)
    by_repo_month = main_for_impact.merge(
        by_commit[
            COMMIT_KEY_COLS
            + [
                "fallback_file_occurrences",
                "fallback_physical_lines",
                "fallback_ncloc",
            ]
        ],
        on=COMMIT_KEY_COLS,
        how="inner",
        validate="many_to_one",
    )
    if not by_repo_month.empty:
        by_repo_month["ncloc_python_snapshot"] = pd.to_numeric(
            by_repo_month["ncloc_python_snapshot"], errors="coerce"
        )
        by_repo_month["fallback_ncloc"] = pd.to_numeric(
            by_repo_month["fallback_ncloc"], errors="coerce"
        )
        by_repo_month["ncloc_python_snapshot_excluding_fallback"] = (
            by_repo_month["ncloc_python_snapshot"] - by_repo_month["fallback_ncloc"]
        )
        by_repo_month["fallback_ncloc_share"] = np.where(
            by_repo_month["ncloc_python_snapshot"].gt(0),
            by_repo_month["fallback_ncloc"]
            / by_repo_month["ncloc_python_snapshot"],
            np.nan,
        )
        by_repo_month = by_repo_month.sort_values(KEY_COLS, kind="stable").reset_index(
            drop=True
        )
        recorder.require_zero(
            "fallback_impact_repo_month_ncloc_exceeds_total",
            int(
                by_repo_month["fallback_ncloc"]
                .gt(by_repo_month["ncloc_python_snapshot"])
                .sum()
            ),
            "fallback_impact",
        )

    summary_rows: list[dict[str, Any]] = []

    def add_summary(
        scope: str,
        group: str,
        metric: str,
        value: Any,
        unit: str,
        detail: str = "",
    ) -> None:
        summary_rows.append(
            {
                "scope": scope,
                "group": group,
                "metric": metric,
                "value": value,
                "unit": unit,
                "detail": detail,
            }
        )

    all_regular_files = float(
        pd.to_numeric(commit_ncloc["regular_python_files_counted"], errors="coerce")
        .fillna(0)
        .sum()
    )
    all_physical_lines = float(
        pd.to_numeric(commit_ncloc["total_physical_lines"], errors="coerce")
        .fillna(0)
        .sum()
    )
    all_commit_ncloc = float(
        pd.to_numeric(commit_ncloc["ncloc_python_snapshot"], errors="coerce")
        .fillna(0)
        .sum()
    )
    fallback_physical_lines_total = float(
        pd.to_numeric(details.get("physical_lines", pd.Series(dtype=float)), errors="coerce")
        .fillna(0)
        .sum()
    )
    fallback_ncloc_total = float(
        pd.to_numeric(details.get("fallback_ncloc", pd.Series(dtype=float)), errors="coerce")
        .fillna(0)
        .sum()
    )
    add_summary("all_commits", "all", "fallback_commit_file_occurrences", len(details), "count")
    add_summary("all_commits", "all", "fallback_unique_repositories", int(details["repo_name"].nunique()) if not details.empty else 0, "count")
    add_summary("all_commits", "all", "fallback_unique_logical_paths", int(details["logical_file_key"].nunique()) if not details.empty else 0, "count")
    add_summary("all_commits", "all", "fallback_unique_commits", int(details[COMMIT_KEY_COLS].drop_duplicates().shape[0]) if not details.empty else 0, "count")
    add_summary("all_commits", "all", "fallback_repeated_occurrences", len(details) - (int(details["logical_file_key"].nunique()) if not details.empty else 0), "count")
    add_summary("all_commits", "all", "all_regular_python_files", int(all_regular_files), "count")
    add_summary("all_commits", "all", "fallback_file_share", safe_ratio(len(details), all_regular_files), "proportion")
    add_summary("all_commits", "all", "fallback_physical_lines", int(fallback_physical_lines_total), "lines")
    add_summary("all_commits", "all", "all_physical_lines", int(all_physical_lines), "lines")
    add_summary("all_commits", "all", "fallback_physical_line_share", safe_ratio(fallback_physical_lines_total, all_physical_lines), "proportion")
    add_summary("all_commits", "all", "fallback_ncloc", int(fallback_ncloc_total), "lines")
    add_summary("all_commits", "all", "all_snapshot_ncloc", int(all_commit_ncloc), "lines")
    add_summary("all_commits", "all", "fallback_ncloc_share", safe_ratio(fallback_ncloc_total, all_commit_ncloc), "proportion")
    add_summary("all_commits", "all", "max_file_fallback_ncloc", int(pd.to_numeric(details.get("fallback_ncloc", pd.Series(dtype=float)), errors="coerce").max()) if not details.empty else 0, "lines")
    add_summary("all_commits", "all", "median_file_fallback_ncloc", float(pd.to_numeric(details.get("fallback_ncloc", pd.Series(dtype=float)), errors="coerce").median()) if not details.empty else np.nan, "lines")
    add_summary("all_commits", "all", "max_commit_fallback_ncloc_share", float(by_commit["fallback_ncloc_share"].max()) if not by_commit.empty else np.nan, "proportion")
    add_summary("all_commits", "all", "median_commit_fallback_ncloc_share", float(by_commit["fallback_ncloc_share"].median()) if not by_commit.empty else np.nan, "proportion")

    main_ncloc_total = float(
        pd.to_numeric(main_panel["ncloc_python_snapshot"], errors="coerce")
        .fillna(0)
        .sum()
    )
    main_fallback_ncloc = float(
        pd.to_numeric(by_repo_month.get("fallback_ncloc", pd.Series(dtype=float)), errors="coerce")
        .fillna(0)
        .sum()
    )
    add_summary("strict_repo_months", "all", "affected_repo_months", len(by_repo_month), "count")
    add_summary("strict_repo_months", "all", "strict_snapshot_ncloc", int(main_ncloc_total), "lines")
    add_summary("strict_repo_months", "all", "fallback_ncloc", int(main_fallback_ncloc), "lines")
    add_summary("strict_repo_months", "all", "fallback_ncloc_share", safe_ratio(main_fallback_ncloc, main_ncloc_total), "proportion")
    add_summary("strict_repo_months", "all", "max_repo_month_fallback_ncloc_share", float(by_repo_month["fallback_ncloc_share"].max()) if not by_repo_month.empty else np.nan, "proportion")
    add_summary("strict_repo_months", "all", "median_affected_repo_month_fallback_ncloc_share", float(by_repo_month["fallback_ncloc_share"].median()) if not by_repo_month.empty else np.nan, "proportion")
    add_summary("strict_repo_months", "all", "repo_months_fallback_share_gt_1pct", int(by_repo_month["fallback_ncloc_share"].gt(0.01).sum()) if not by_repo_month.empty else 0, "count")
    add_summary("strict_repo_months", "all", "repo_months_fallback_share_gt_5pct", int(by_repo_month["fallback_ncloc_share"].gt(0.05).sum()) if not by_repo_month.empty else 0, "count")

    for source in ["treatment", "control"]:
        source_details = details.loc[details["dataset_source"].eq(source)] if not details.empty else details
        source_commits = commit_ncloc.loc[commit_ncloc["dataset_source"].eq(source)]
        source_all_files = float(
            pd.to_numeric(source_commits["regular_python_files_counted"], errors="coerce")
            .fillna(0)
            .sum()
        )
        source_all_physical_lines = float(
            pd.to_numeric(source_commits["total_physical_lines"], errors="coerce")
            .fillna(0)
            .sum()
        )
        source_all_ncloc = float(
            pd.to_numeric(source_commits["ncloc_python_snapshot"], errors="coerce")
            .fillna(0)
            .sum()
        )
        source_fallback_physical_lines = float(
            pd.to_numeric(source_details.get("physical_lines", pd.Series(dtype=float)), errors="coerce")
            .fillna(0)
            .sum()
        )
        source_fallback_ncloc = float(
            pd.to_numeric(source_details.get("fallback_ncloc", pd.Series(dtype=float)), errors="coerce")
            .fillna(0)
            .sum()
        )
        add_summary("all_commits", source, "fallback_commit_file_occurrences", len(source_details), "count")
        add_summary("all_commits", source, "fallback_unique_repositories", int(source_details["repo_name"].nunique()) if not source_details.empty else 0, "count")
        add_summary("all_commits", source, "fallback_unique_logical_paths", int(source_details["logical_file_key"].nunique()) if not source_details.empty else 0, "count")
        add_summary("all_commits", source, "all_regular_python_files", int(source_all_files), "count")
        add_summary("all_commits", source, "fallback_file_share", safe_ratio(len(source_details), source_all_files), "proportion")
        add_summary("all_commits", source, "fallback_physical_lines", int(source_fallback_physical_lines), "lines")
        add_summary("all_commits", source, "all_physical_lines", int(source_all_physical_lines), "lines")
        add_summary("all_commits", source, "fallback_physical_line_share", safe_ratio(source_fallback_physical_lines, source_all_physical_lines), "proportion")
        add_summary("all_commits", source, "fallback_ncloc", int(source_fallback_ncloc), "lines")
        add_summary("all_commits", source, "all_snapshot_ncloc", int(source_all_ncloc), "lines")
        add_summary("all_commits", source, "fallback_ncloc_share", safe_ratio(source_fallback_ncloc, source_all_ncloc), "proportion")

        source_main = main_panel.loc[main_panel["dataset_source"].eq(source)]
        source_repo_month = by_repo_month.loc[by_repo_month["dataset_source"].eq(source)] if not by_repo_month.empty else by_repo_month
        source_main_ncloc = float(
            pd.to_numeric(source_main["ncloc_python_snapshot"], errors="coerce")
            .fillna(0)
            .sum()
        )
        source_main_fallback = float(
            pd.to_numeric(source_repo_month.get("fallback_ncloc", pd.Series(dtype=float)), errors="coerce")
            .fillna(0)
            .sum()
        )
        add_summary("strict_repo_months", source, "affected_repo_months", len(source_repo_month), "count")
        add_summary("strict_repo_months", source, "fallback_ncloc", int(source_main_fallback), "lines")
        add_summary("strict_repo_months", source, "strict_snapshot_ncloc", int(source_main_ncloc), "lines")
        add_summary("strict_repo_months", source, "fallback_ncloc_share", safe_ratio(source_main_fallback, source_main_ncloc), "proportion")

    for error_type, part in details.groupby("error_type") if not details.empty else []:
        error_physical_lines = float(pd.to_numeric(part["physical_lines"], errors="coerce").fillna(0).sum())
        error_ncloc = float(pd.to_numeric(part["fallback_ncloc"], errors="coerce").fillna(0).sum())
        add_summary("error_type", str(error_type), "fallback_commit_file_occurrences", len(part), "count")
        add_summary("error_type", str(error_type), "fallback_unique_repositories", int(part["repo_name"].nunique()), "count")
        add_summary("error_type", str(error_type), "fallback_unique_logical_paths", int(part["logical_file_key"].nunique()), "count")
        add_summary("error_type", str(error_type), "fallback_physical_lines", int(error_physical_lines), "lines")
        add_summary("error_type", str(error_type), "share_of_fallback_physical_lines", safe_ratio(error_physical_lines, fallback_physical_lines_total), "proportion")
        add_summary("error_type", str(error_type), "fallback_ncloc", int(error_ncloc), "lines")
        add_summary("error_type", str(error_type), "share_of_fallback_ncloc", safe_ratio(error_ncloc, fallback_ncloc_total), "proportion")

    summary = pd.DataFrame(summary_rows)
    recorder.require_zero(
        "fallback_impact_summary_nonfinite_proportions",
        int(
            (
                summary["unit"].eq("proportion")
                & pd.to_numeric(summary["value"], errors="coerce").notna()
                & ~np.isfinite(pd.to_numeric(summary["value"], errors="coerce"))
            ).sum()
        ),
        "fallback_impact",
    )
    recorder.require_zero(
        "fallback_impact_proportions_outside_zero_one",
        int(
            (
                summary["unit"].eq("proportion")
                & pd.to_numeric(summary["value"], errors="coerce").notna()
                & ~pd.to_numeric(summary["value"], errors="coerce").between(0, 1)
            ).sum()
        ),
        "fallback_impact",
    )
    return details, by_commit, by_repo_month, summary


def main() -> int:
    """Run all validation checks and write detailed artifacts."""
    args = parse_args()
    args.output_dir.mkdir(parents=True, exist_ok=True)

    for path, label in [
        (args.input_panel, "AGC DiD input panel"),
