def run_git_bytes(repo_dir: Path, args: Iterable[str]) -> subprocess.CompletedProcess[bytes]:
    return subprocess.run(
        ["git", "-C", str(repo_dir), *list(args)],
        capture_output=True,
        check=False,
    )


def require_git_bytes(result: subprocess.CompletedProcess[bytes], label: str) -> bytes:
    if result.returncode != 0:
        message = result.stderr.decode("utf-8", errors="replace").strip()
        if not message:
            message = result.stdout.decode("utf-8", errors="replace").strip()
        raise RuntimeError(f"{label}: {message}")
    return result.stdout


def valid_sha(value: str) -> bool:
    return bool(FULL_SHA_RE.fullmatch(value.strip()))


def repo_slug(repo_name: str) -> str:
    return repo_name.replace("/", "_")


def safe_path_part(value: str) -> str:
    cleaned = re.sub(r"[^A-Za-z0-9_.-]+", "_", value.strip())
    return cleaned or "unknown"


def eligible_python_path(path_text: str) -> bool:
    if not path_text:
        return False
    path = PurePosixPath(path_text)
    return (
        not path.is_absolute()
        and path.suffix.lower() == ".py"
        and not any(part in EXCLUDED_PARTS for part in path.parts)
        and all(part not in {"", ".", ".."} for part in path.parts)
    )


def decode_git_path(raw: bytes) -> str:
    return raw.decode("utf-8", errors="surrogateescape")


def parse_name_status_z(payload: bytes) -> list[ChangedPath]:
    tokens = payload.split(b"\0")
    if tokens and tokens[-1] == b"":
        tokens.pop()
    rows: list[ChangedPath] = []
    index = 0
    while index < len(tokens):
        status = decode_git_path(tokens[index])
        index += 1
        if status.startswith(("R", "C")):
            if index + 1 >= len(tokens):
                raise ValueError("Malformed rename/copy name-status output")
            old_path = decode_git_path(tokens[index])
            new_path = decode_git_path(tokens[index + 1])
            index += 2
        else:
            if index >= len(tokens):
                raise ValueError("Malformed name-status output")
            path = decode_git_path(tokens[index])
            index += 1
            old_path = "" if status.startswith("A") else path
            new_path = "" if status.startswith("D") else path
        rows.append(ChangedPath(status=status, old_path=old_path, new_path=new_path))
    return rows


def list_changed_paths(repo_dir: Path, parent: str, current: str) -> list[ChangedPath]:
    if parent == EMPTY_TREE_SHA:
        args = [
            "diff-tree",
            "--root",
            "--no-commit-id",
            "--name-status",
            "-r",
            "-M",
            "-z",
            current,
            "--",
        ]
    else:
        args = [
            "diff-tree",
            "--no-commit-id",
            "--name-status",
            "-r",
            "-M",
            "-z",
            parent,
            current,
            "--",
        ]
    payload = require_git_bytes(run_git_bytes(repo_dir, args), "git diff-tree failed")
    return parse_name_status_z(payload)


def git_blob(repo_dir: Path, commit: str, relative_path: str) -> bytes:
    if commit == EMPTY_TREE_SHA or not relative_path:
        raise FileNotFoundError("Blob does not exist in empty tree")
    spec = f"{commit}:{relative_path}"
    result = run_git_bytes(repo_dir, ["show", spec])
    if result.returncode != 0:
        message = result.stderr.decode("utf-8", errors="replace").strip()
        raise FileNotFoundError(f"Cannot read {spec}: {message}")
    return result.stdout


def decode_python_source(payload: bytes) -> str:
    reader = io.BytesIO(payload).readline
    encoding, _ = tokenize.detect_encoding(reader)
    return payload.decode(encoding)


def structural_sha(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def content_sha(payload: bytes) -> str:
    return hashlib.sha256(payload).hexdigest()


class NestedDefinitionStripper(ast.NodeTransformer):
    """Remove nested named definitions from an enclosing function fingerprint."""

    def visit_FunctionDef(self, node: ast.FunctionDef) -> Any:
        return None

    def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> Any:
        return None

    def visit_ClassDef(self, node: ast.ClassDef) -> Any:
        return None


def direct_function_fingerprint(node: ast.FunctionDef | ast.AsyncFunctionDef) -> str:
    clone = copy.deepcopy(node)
    stripper = NestedDefinitionStripper()
    clone.body = [
        transformed
        for statement in clone.body
        if (transformed := stripper.visit(statement)) is not None
    ]
    return ast.dump(clone, annotate_fields=True, include_attributes=False)


def source_start_line(node: ast.FunctionDef | ast.AsyncFunctionDef) -> int:
    decorator_lines = [
        int(decorator.lineno)
        for decorator in node.decorator_list
        if hasattr(decorator, "lineno")
    ]
    return min([int(node.lineno), *decorator_lines])


def render_function_source(
    node: ast.FunctionDef | ast.AsyncFunctionDef,
    qualified_name: str,
    kind: str,
) -> str:
    """Render one named function as standalone parseable Python source."""

    start_line = source_start_line(node)
    end_line = int(getattr(node, "end_lineno", node.lineno))
    try:
        rendered = ast.unparse(copy.deepcopy(node)).rstrip() + "\n"
    except Exception as exc:
        raise FunctionArtifactError(
            "function_artifact_render",
            qualified_name,
            node.name,
            kind,
            start_line,
            end_line,
            exc,
        ) from exc

    try:
        validation_tree = ast.parse(
            rendered,
            filename=f"<function-artifact:{qualified_name}>",
            type_comments=True,
        )
        if (
            len(validation_tree.body) != 1
            or not isinstance(
                validation_tree.body[0],
                (ast.FunctionDef, ast.AsyncFunctionDef),
            )
        ):
            raise ValueError("Rendered artifact is not exactly one named function")
    except Exception as exc:
        raise FunctionArtifactError(
            "function_artifact_validation",
            qualified_name,
            node.name,
            kind,
            start_line,
            end_line,
            exc,
        ) from exc
    return rendered


def function_kind(
    node: ast.FunctionDef | ast.AsyncFunctionDef,
    scope_kinds: Sequence[str],
) -> str:
    is_async = isinstance(node, ast.AsyncFunctionDef)
    if scope_kinds and scope_kinds[-1] == "class":
        return "async_method" if is_async else "method"
    if "function" in scope_kinds:
        return "nested_async_function" if is_async else "nested_function"
    return "module_async_function" if is_async else "module_function"


def iter_child_definitions(statements: Sequence[ast.stmt]) -> Iterator[ast.AST]:
    for statement in statements:
        yield statement


def extract_functions(
    source: str,
    *,
    filename: str = "<unknown>",
    render_sources: bool = True,
) -> list[FunctionRecord]:
    tree = ast.parse(source, filename=filename, type_comments=True)
    occurrence_counts: Counter[str] = Counter()
    records: list[FunctionRecord] = []

    def walk_statements(
        statements: Sequence[ast.stmt],
        scope_names: list[str],
        scope_kinds: list[str],
    ) -> None:
        for statement in iter_child_definitions(statements):
            if isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef)):
                qualified_base = ".".join([*scope_names, statement.name])
                occurrence_counts[qualified_base] += 1
                occurrence_index = occurrence_counts[qualified_base]
                kind = function_kind(statement, scope_kinds)
                start_line = source_start_line(statement)
                end_line = int(getattr(statement, "end_lineno", statement.lineno))
                source_text = (
                    render_function_source(statement, qualified_base, kind)
                    if render_sources
                    else ""
                )
                fingerprint = direct_function_fingerprint(statement)
                records.append(
                    FunctionRecord(
                        qualified_name=qualified_base,
                        function_name=statement.name,
                        function_kind=kind,
                        occurrence_index=occurrence_index,
                        start_line=start_line,
                        end_line=end_line,
                        structural_text=fingerprint,
                        structural_sha256=structural_sha(fingerprint),
                        source_text=source_text,
                    )
                )
                walk_statements(
                    statement.body,
                    [*scope_names, statement.name],
                    [*scope_kinds, "function"],
                )
            elif isinstance(statement, ast.ClassDef):
                walk_statements(
                    statement.body,
                    [*scope_names, statement.name],
                    [*scope_kinds, "class"],
                )
            else:
                nested_bodies: list[Sequence[ast.stmt]] = []
                for field_name in (
                    "body",
                    "orelse",
                    "finalbody",
                ):
                    value = getattr(statement, field_name, None)
                    if isinstance(value, list) and value and all(
                        isinstance(item, ast.stmt) for item in value
                    ):
                        nested_bodies.append(value)
                handlers = getattr(statement, "handlers", None)
                if isinstance(handlers, list):
                    for handler in handlers:
                        if isinstance(handler, ast.ExceptHandler):
                            nested_bodies.append(handler.body)
                cases = getattr(statement, "cases", None)
                if isinstance(cases, list):
                    for case in cases:
                        body = getattr(case, "body", None)
                        if isinstance(body, list):
                            nested_bodies.append(body)
                for body in nested_bodies:
                    walk_statements(body, scope_names, scope_kinds)

    walk_statements(tree.body, [], [])
    return records


def compare_function_sets(
    parent_records: Sequence[FunctionRecord],
    current_records: Sequence[FunctionRecord],
) -> tuple[list[tuple[FunctionRecord, FunctionRecord | None, str]], int, int]:
    parent_by_key = {record.identity: record for record in parent_records}
    current_by_key = {record.identity: record for record in current_records}
    events: list[tuple[FunctionRecord, FunctionRecord | None, str]] = []
    unchanged = 0

    for key, current_record in current_by_key.items():
        parent_record = parent_by_key.get(key)
        if parent_record is None:
            events.append((current_record, None, "added"))
        elif current_record.structural_sha256 != parent_record.structural_sha256:
            events.append((current_record, parent_record, "modified"))
        else:
            unchanged += 1

    deleted_ignored = sum(key not in current_by_key for key in parent_by_key)
    return events, unchanged, deleted_ignored


def deterministic_event_id(
    source: str,
    repo_name: str,
    month: str,
    commit: str,
    relative_path: str,
    qualified_name: str,
    occurrence_index: int,
    change_type: str,
) -> str:
    payload = "\0".join(
        [
            source,
            repo_name,
            month,
            commit,
            relative_path,
            qualified_name,
            str(occurrence_index),
            change_type,
        ]
    ).encode("utf-8", errors="surrogateescape")
    return hashlib.sha256(payload).hexdigest()[:24]


def atomic_csv(frame: pd.DataFrame, path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    frame.to_csv(temporary, index=False, quoting=csv.QUOTE_MINIMAL)
    os.replace(temporary, path)


def atomic_json(payload: dict[str, Any], path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(
        json.dumps(payload, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    os.replace(temporary, path)


def write_source_artifact(
    root: Path,
    dataset_source: str,
    repo_name: str,
    month: str,
    commit: str,
    event_id: str,
    source_text: str,
) -> tuple[str, str, int]:
    relative = Path(
        safe_path_part(dataset_source),
        safe_path_part(repo_slug(repo_name)),
        safe_path_part(month),
        safe_path_part(commit),
        f"{event_id}.py",
    )
    destination = root / relative
    destination.parent.mkdir(parents=True, exist_ok=True)
    payload = source_text.encode("utf-8")
    temporary = destination.with_suffix(".py.tmp")
    temporary.write_bytes(payload)
    os.replace(temporary, destination)
    return relative.as_posix(), content_sha(payload), len(payload)


def load_pairs(path: Path) -> tuple[pd.DataFrame, pd.DataFrame]:
    all_pairs = pd.read_csv(
        path,
        dtype={
            "scan_parent_commit": "string",
            "scan_current_commit": "string",
        },
        low_memory=False,
    )
    missing = sorted(PAIR_REQUIRED - set(all_pairs.columns))
    if missing:
        raise ValueError(f"Commit-pair input missing columns: {missing}")

    for column in [
        "dataset_source",
        "repo_name",
        "month",
        "scan_parent_commit",
        "scan_current_commit",
        "repo_dir",
    ]:
        all_pairs[column] = all_pairs[column].fillna("").astype(str).str.strip()
    for column in ["commit_order", "primary_scan_eligible"]:
        all_pairs[column] = pd.to_numeric(all_pairs[column], errors="coerce")
        if all_pairs[column].isna().any():
            raise ValueError(f"Commit-pair column must be numeric: {column}")
        all_pairs[column] = all_pairs[column].astype(int)

    invalid_sources = sorted(
        set(all_pairs["dataset_source"]) - {"treatment", "control"}
    )
    if invalid_sources:
        raise ValueError(f"Unsupported dataset sources: {invalid_sources}")

    invalid_eligibility = sorted(
        set(all_pairs["primary_scan_eligible"]) - {0, 1}
    )
    if invalid_eligibility:
        raise ValueError(
            f"Unsupported primary_scan_eligible values: {invalid_eligibility}"
        )

    duplicate_all_keys = int(all_pairs.duplicated(PAIR_KEY_COLUMNS).sum())
    if duplicate_all_keys:
        raise ValueError(f"Duplicate commit-pair rows: {duplicate_all_keys}")

    all_pairs = all_pairs.sort_values(
        ["dataset_source", "repo_name", "month", "commit_order"]
    ).reset_index(drop=True)
    eligible_pairs = all_pairs.loc[
        all_pairs["primary_scan_eligible"].eq(1)
    ].copy().reset_index(drop=True)
    return all_pairs, eligible_pairs


def select_pair_scope(
    all_pairs: pd.DataFrame,
    eligible_pairs: pd.DataFrame,
    repositories: Sequence[str],
    max_pairs: int,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    requested = [value.strip() for value in repositories if value.strip()]
    if requested:
        available = set(all_pairs["repo_name"])
        missing = sorted(set(requested) - available)
        if missing:
            raise ValueError(f"Requested repositories not found: {missing}")
        all_pairs = all_pairs.loc[all_pairs["repo_name"].isin(requested)].copy()
        eligible_pairs = eligible_pairs.loc[
            eligible_pairs["repo_name"].isin(requested)
        ].copy()

    if max_pairs > 0:
        eligible_pairs = eligible_pairs.head(max_pairs).copy()
        selected_months = eligible_pairs[[
            "dataset_source",
            "repo_name",
            "month",
        ]].drop_duplicates()
        all_pairs = all_pairs.merge(
            selected_months,
            on=["dataset_source", "repo_name", "month"],
            how="inner",
        )

    return (
        all_pairs.reset_index(drop=True),
        eligible_pairs.reset_index(drop=True),
    )


def resolve_repo_dir(
    row: Any,
    treatment_clone_dir: Path,
    control_clone_dir: Path,
) -> Path:
    expected_root = (
        treatment_clone_dir
        if str(row.dataset_source) == "treatment"
        else control_clone_dir
    )
    expected = expected_root / repo_slug(str(row.repo_name))
    supplied = Path(str(row.repo_dir))
    if supplied.is_dir() and (supplied / ".git").exists():
        return supplied.resolve()
    return expected.resolve()


def read_function_records(
    repo_dir: Path,
    commit: str,
    relative_path: str,
    role: str,
    *,
    render_sources: bool,
) -> list[FunctionRecord]:
    try:
        payload = git_blob(repo_dir, commit, relative_path)
    except Exception as exc:
        raise FileExtractionError(f"{role}_blob_read", exc) from exc

    try:
        source = decode_python_source(payload)
    except Exception as exc:
        raise FileExtractionError(f"{role}_file_decode", exc) from exc

    try:
        return extract_functions(
            source,
            filename=f"{commit}:{relative_path}",
            render_sources=render_sources,
        )
    except FunctionArtifactError:
        raise
    except SyntaxError as exc:
        raise FileExtractionError(f"{role}_file_parse", exc) from exc
    except Exception as exc:
        raise FileExtractionError(f"{role}_function_extraction", exc) from exc


def error_row(
    *,
    dataset_source: str,
    repo_name: str,
    month: str,
    commit: str,
    parent_commit: str,
    relative_path: str,
    stage: str,
    error: BaseException,
    function_error: FunctionArtifactError | None = None,
    function_record: FunctionRecord | None = None,
) -> dict[str, Any]:
    if function_error is not None:
        qualified_name = function_error.qualified_name
        function_name = function_error.function_name
        kind = function_error.function_kind
        start_line = function_error.start_line
        end_line = function_error.end_line
    elif function_record is not None:
        qualified_name = function_record.qualified_name
        function_name = function_record.function_name
        kind = function_record.function_kind
        start_line = function_record.start_line
        end_line = function_record.end_line
    else:
        qualified_name = ""
        function_name = ""
        kind = ""
        start_line = ""
        end_line = ""

    return {
        "dataset_source": dataset_source,
        "repo_name": repo_name,
        "time": month,
        "commit": commit,
        "parent_commit": parent_commit,
        "relative_path": relative_path,
        "stage": stage,
        "error": f"{type(error).__name__}: {error}",
        "qualified_function_name": qualified_name,
        "function_name": function_name,
        "function_kind": kind,
        "start_line": start_line,
        "end_line": end_line,
    }


def audit_row(
    *,
    dataset_source: str,
    repo_name: str,
    month: str,
    commit: str,
    parent_commit: str,
    commit_order: int,
    diff_status: str = "",
    relative_path: str = "",
    parent_relative_path: str = "",
    current_functions: int = 0,
    parent_functions: int = 0,
    added_function_events: int = 0,
    modified_function_events: int = 0,
    unchanged_functions: int = 0,
    deleted_functions_ignored: int = 0,
    file_status: str = "ok",
    error_message: str = "",
) -> dict[str, Any]:
    return {
        "dataset_source": dataset_source,
        "repo_name": repo_name,
        "time": month,
        "commit": commit,
        "parent_commit": parent_commit,
        "commit_order": commit_order,
        "diff_status": diff_status,
        "relative_path": relative_path,
        "parent_relative_path": parent_relative_path,
        "current_functions": current_functions,
        "parent_functions": parent_functions,
        "added_function_events": added_function_events,
        "modified_function_events": modified_function_events,
        "unchanged_functions": unchanged_functions,
        "deleted_functions_ignored": deleted_functions_ignored,
        "file_status": file_status,
        "error_message": error_message,
    }


def extract_events(
    pairs: pd.DataFrame,
    treatment_clone_dir: Path,
    control_clone_dir: Path,
    source_root: Path,
    progress_every: int,
) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    manifest_rows: list[dict[str, Any]] = []
    audit_rows: list[dict[str, Any]] = []
    error_rows: list[dict[str, Any]] = []

    total = len(pairs)
    for pair_number, row in enumerate(pairs.itertuples(index=False), start=1):
        dataset_source = str(row.dataset_source)
        repo_name = str(row.repo_name)
        month = str(row.month)
        parent_commit = str(row.scan_parent_commit)
        current_commit = str(row.scan_current_commit)
        commit_order = int(row.commit_order)
        repo_dir = resolve_repo_dir(
            row,
            treatment_clone_dir,
            control_clone_dir,
        )

        try:
            if not (repo_dir / ".git").exists():
                raise FileNotFoundError(f"Missing Git clone: {repo_dir}")
            if parent_commit != EMPTY_TREE_SHA and not valid_sha(parent_commit):
                raise ValueError(f"Invalid parent commit: {parent_commit}")
            if not valid_sha(current_commit):
                raise ValueError(f"Invalid current commit: {current_commit}")
            changed_paths = list_changed_paths(repo_dir, parent_commit, current_commit)
        except Exception as exc:
            error_rows.append(
                error_row(
                    dataset_source=dataset_source,
                    repo_name=repo_name,
                    month=month,
                    commit=current_commit,
                    parent_commit=parent_commit,
                    relative_path="",
                    stage="commit_diff",
                    error=exc,
                )
            )
            audit_rows.append(
                audit_row(
                    dataset_source=dataset_source,
                    repo_name=repo_name,
                    month=month,
                    commit=current_commit,
                    parent_commit=parent_commit,
                    commit_order=commit_order,
                    file_status="commit_diff_error",
                    error_message=f"{type(exc).__name__}: {exc}",
                )
            )
            continue

        python_change_seen = False
        for changed in changed_paths:
            current_path = changed.new_path
            parent_path = changed.old_path
            if not eligible_python_path(current_path):
                continue
            python_change_seen = True
            current_records: list[FunctionRecord] = []
            parent_records: list[FunctionRecord] = []
            created_artifacts: list[Path] = []

            try:
                current_records = read_function_records(
                    repo_dir,
                    current_commit,
                    current_path,
                    "current",
                    render_sources=True,
                )

                parent_is_python = eligible_python_path(parent_path)
                if parent_is_python and not changed.status.startswith("A"):
                    parent_records = read_function_records(
                        repo_dir,
                        parent_commit,
                        parent_path,
                        "parent",
                        render_sources=False,
                    )

                events, unchanged, deleted_ignored = compare_function_sets(
                    parent_records,
                    current_records,
                )
                added_count = 0
                modified_count = 0
                file_manifest_rows: list[dict[str, Any]] = []

                for current_record, parent_record, change_type in events:
                    event_id = deterministic_event_id(
                        dataset_source,
                        repo_name,
                        month,
                        current_commit,
                        current_path,
                        current_record.qualified_name,
                        current_record.occurrence_index,
                        change_type,
                    )
                    try:
                        (
                            relative_source_path,
                            source_hash,
                            source_bytes,
                        ) = write_source_artifact(
                            source_root,
                            dataset_source,
                            repo_name,
                            month,
                            current_commit,
                            event_id,
                            current_record.source_text,
                        )
                    except Exception as exc:
                        raise FunctionArtifactError(
                            "function_artifact_write",
                            current_record.qualified_name,
                            current_record.function_name,
                            current_record.function_kind,
                            current_record.start_line,
                            current_record.end_line,
                            exc,
                        ) from exc
                    created_artifacts.append(source_root / relative_source_path)
                    file_manifest_rows.append(
                        {
                            "function_event_id": event_id,
                            "dataset_source": dataset_source,
                            "repo_name": repo_name,
                            "time": month,
                            "commit": current_commit,
                            "parent_commit": parent_commit,
                            "commit_order": commit_order,
                            "relative_path": current_path,
                            "parent_relative_path": parent_path,
                            "diff_status": changed.status,
                            "qualified_function_name": current_record.qualified_name,
                            "function_name": current_record.function_name,
                            "function_kind": current_record.function_kind,
                            "occurrence_index": current_record.occurrence_index,
                            "change_type": change_type,
                            "start_line": current_record.start_line,
                            "end_line": current_record.end_line,
                            "parent_start_line": (
                                ""
                                if parent_record is None
                                else parent_record.start_line
                            ),
                            "parent_end_line": (
                                ""
                                if parent_record is None
                                else parent_record.end_line
                            ),
                            "structural_sha256": current_record.structural_sha256,
                            "parent_structural_sha256": (
                                ""
                                if parent_record is None
                                else parent_record.structural_sha256
                            ),
                            "function_source_relative_path": relative_source_path,
                            "content_sha256": source_hash,
                            "source_bytes": source_bytes,
                        }
                    )
                    added_count += int(change_type == "added")
                    modified_count += int(change_type == "modified")

                manifest_rows.extend(file_manifest_rows)
                audit_rows.append(
                    audit_row(
                        dataset_source=dataset_source,
                        repo_name=repo_name,
                        month=month,
                        commit=current_commit,
                        parent_commit=parent_commit,
                        commit_order=commit_order,
                        diff_status=changed.status,
                        relative_path=current_path,
                        parent_relative_path=parent_path,
                        current_functions=len(current_records),
                        parent_functions=len(parent_records),
                        added_function_events=added_count,
                        modified_function_events=modified_count,
                        unchanged_functions=unchanged,
                        deleted_functions_ignored=deleted_ignored,
                    )
                )
            except FunctionArtifactError as exc:
                for artifact in created_artifacts:
                    artifact.unlink(missing_ok=True)
                message = str(exc)
                audit_rows.append(
                    audit_row(
                        dataset_source=dataset_source,
                        repo_name=repo_name,
                        month=month,
                        commit=current_commit,
                        parent_commit=parent_commit,
                        commit_order=commit_order,
                        diff_status=changed.status,
                        relative_path=current_path,
                        parent_relative_path=parent_path,
                        current_functions=len(current_records),
                        parent_functions=len(parent_records),
                        file_status=exc.stage,
                        error_message=message,
                    )
                )
                error_rows.append(
                    error_row(
                        dataset_source=dataset_source,
                        repo_name=repo_name,
                        month=month,
                        commit=current_commit,
                        parent_commit=parent_commit,
                        relative_path=current_path,
                        stage=exc.stage,
                        error=exc.cause,
                        function_error=exc,
                    )
                )
            except FileExtractionError as exc:
                for artifact in created_artifacts:
                    artifact.unlink(missing_ok=True)
                message = str(exc)
                audit_rows.append(
                    audit_row(
                        dataset_source=dataset_source,
                        repo_name=repo_name,
                        month=month,
                        commit=current_commit,
                        parent_commit=parent_commit,
                        commit_order=commit_order,
                        diff_status=changed.status,
                        relative_path=current_path,
                        parent_relative_path=parent_path,
                        current_functions=len(current_records),
                        parent_functions=len(parent_records),
                        file_status=exc.stage,
                        error_message=message,
                    )
                )
                error_rows.append(
                    error_row(
                        dataset_source=dataset_source,
                        repo_name=repo_name,
                        month=month,
                        commit=current_commit,
                        parent_commit=parent_commit,
                        relative_path=current_path,
                        stage=exc.stage,
                        error=exc.cause,
                    )
                )
            except Exception as exc:
                for artifact in created_artifacts:
                    artifact.unlink(missing_ok=True)
                message = f"{type(exc).__name__}: {exc}"
                audit_rows.append(
                    audit_row(
                        dataset_source=dataset_source,
                        repo_name=repo_name,
                        month=month,
                        commit=current_commit,
                        parent_commit=parent_commit,
                        commit_order=commit_order,
                        diff_status=changed.status,
                        relative_path=current_path,
                        parent_relative_path=parent_path,
                        current_functions=len(current_records),
                        parent_functions=len(parent_records),
                        file_status="python_function_extraction",
                        error_message=message,
                    )
                )
                error_rows.append(
                    error_row(
                        dataset_source=dataset_source,
                        repo_name=repo_name,
                        month=month,
                        commit=current_commit,
                        parent_commit=parent_commit,
                        relative_path=current_path,
                        stage="python_function_extraction",
                        error=exc,
                    )
                )

        if not python_change_seen:
            audit_rows.append(
                audit_row(
                    dataset_source=dataset_source,
                    repo_name=repo_name,
                    month=month,
                    commit=current_commit,
                    parent_commit=parent_commit,
                    commit_order=commit_order,
                    file_status="no_python_changes",
                )
            )

        if progress_every > 0 and (
            pair_number % progress_every == 0 or pair_number == total
        ):
            print(
                f"Function-event extraction: {pair_number}/{total} commit pairs; "
                f"events={len(manifest_rows)} errors={len(error_rows)}",
                flush=True,
            )

    manifest = pd.DataFrame(manifest_rows, columns=MANIFEST_COLUMNS)
    audit = pd.DataFrame(audit_rows, columns=AUDIT_COLUMNS)
    errors = pd.DataFrame(error_rows, columns=ERROR_COLUMNS)
    return manifest, audit, errors

def build_repo_month_counts(
    all_pairs: pd.DataFrame,
    eligible_pairs: pd.DataFrame,
    manifest: pd.DataFrame,
    audit: pd.DataFrame,
) -> pd.DataFrame:
    base = (
        all_pairs[["dataset_source", "repo_name", "month"]]
        .drop_duplicates()
        .rename(columns={"month": "time"})
        .sort_values(["dataset_source", "repo_name", "time"])
        .reset_index(drop=True)
    )

    eligible_counts = (
        eligible_pairs.groupby(
            ["dataset_source", "repo_name", "month"],
            as_index=False,
        )
        .agg(commits_scanned=("scan_current_commit", "nunique"))
        .rename(columns={"month": "time"})
    )
    base = base.merge(
        eligible_counts,
        on=["dataset_source", "repo_name", "time"],
        how="left",
    )
    base["commits_scanned"] = (
        base["commits_scanned"].fillna(0).astype(int)
    )

    python_commit_rows = audit.loc[
        audit["file_status"].ne("no_python_changes")
        & audit["relative_path"].astype(str).str.len().gt(0)
    ]
    python_commits = (
        python_commit_rows.groupby(
            ["dataset_source", "repo_name", "time"],
            as_index=False,
        )
        .agg(commits_with_python_changes=("commit", "nunique"))
    )

    if manifest.empty:
        output = base.copy()
        output["commits_with_python_changes"] = 0
        for column in REPO_MONTH_COLUMNS[5:]:
            output[column] = 0
        return output[REPO_MONTH_COLUMNS]

    manifest_for_counts = manifest.copy()
    manifest_for_counts["_function_identity"] = (
        manifest_for_counts["relative_path"].astype(str)
        + "\0"
        + manifest_for_counts["qualified_function_name"].astype(str)
        + "\0"
        + manifest_for_counts["occurrence_index"].astype(str)
    )
    event_counts = (
        manifest_for_counts.groupby(
            ["dataset_source", "repo_name", "time"],
            as_index=False,
        )
        .agg(
            commits_with_function_change_events=("commit", "nunique"),
            function_change_events=("function_event_id", "size"),
            added_function_events=(
                "change_type",
                lambda values: int((values == "added").sum()),
            ),
            modified_function_events=(
                "change_type",
                lambda values: int((values == "modified").sum()),
            ),
            unique_changed_functions=("_function_identity", "nunique"),
            unique_changed_files=("relative_path", "nunique"),
        )
    )

    output = base.merge(
        python_commits,
        on=["dataset_source", "repo_name", "time"],
        how="left",
    ).merge(
        event_counts,
        on=["dataset_source", "repo_name", "time"],
        how="left",
    )
    numeric = [
        column
        for column in REPO_MONTH_COLUMNS
        if column not in {"dataset_source", "repo_name", "time"}
    ]
    output[numeric] = output[numeric].fillna(0).astype(int)
    return output[REPO_MONTH_COLUMNS]

def frame_key_set(
    frame: pd.DataFrame,
    columns: Sequence[str],
) -> set[tuple[str, ...]]:
    if frame.empty:
        return set()
    normalized = frame.loc[:, list(columns)].fillna("").astype(str)
    return set(normalized.itertuples(index=False, name=None))


def build_checks(
    all_pairs: pd.DataFrame,
    eligible_pairs: pd.DataFrame,
    manifest: pd.DataFrame,
    audit: pd.DataFrame,
    errors: pd.DataFrame,
    repo_month_counts: pd.DataFrame,
    source_root: Path,
) -> pd.DataFrame:
    checks: list[dict[str, Any]] = []

    def add(section: str, check: str, passed: bool, value: Any) -> None:
        checks.append(
            {
                "section": section,
                "check": check,
                "passed": int(bool(passed)),
                "value": value,
            }
        )

    duplicate_event_ids = int(manifest["function_event_id"].duplicated().sum())
    add(
        "manifest",
        "function_event_ids_unique",
        duplicate_event_ids == 0,
        duplicate_event_ids,
    )
    invalid_change_types = int(
        (~manifest["change_type"].isin(["added", "modified"])).sum()
    )
    add(
        "manifest",
        "change_types_valid",
        invalid_change_types == 0,
        invalid_change_types,
    )
    valid_kinds = {
        "module_function",
        "module_async_function",
        "method",
        "async_method",
        "nested_function",
        "nested_async_function",
    }
    invalid_kinds = int((~manifest["function_kind"].isin(valid_kinds)).sum())
    add(
        "manifest",
        "function_kinds_valid",
        invalid_kinds == 0,
        invalid_kinds,
    )

    missing_sources = 0
    hash_mismatches = 0
    for row in manifest.itertuples(index=False):
        path = source_root / str(row.function_source_relative_path)
        if not path.is_file():
            missing_sources += 1
            continue
        if content_sha(path.read_bytes()) != str(row.content_sha256):
            hash_mismatches += 1
    add(
        "sources",
        "all_source_artifacts_present",
        missing_sources == 0,
        missing_sources,
    )
    add(
        "sources",
        "source_hashes_match_manifest",
        hash_mismatches == 0,
        hash_mismatches,
    )

    arithmetic_errors = int(
        (
            audit["added_function_events"]
            + audit["modified_function_events"]
            < 0
        ).sum()
    )
    add(
        "arithmetic",
        "event_counts_nonnegative",
        arithmetic_errors == 0,
        arithmetic_errors,
    )
    manifest_from_audit = int(
        audit["added_function_events"].sum()
        + audit["modified_function_events"].sum()
    )
    add(
        "arithmetic",
        "audit_event_count_matches_manifest",
        manifest_from_audit == len(manifest),
        f"{manifest_from_audit}:{len(manifest)}",
    )
    repo_month_event_total = int(repo_month_counts["function_change_events"].sum())
    add(
        "arithmetic",
        "repo_month_event_count_matches_manifest",
        repo_month_event_total == len(manifest),
        f"{repo_month_event_total}:{len(manifest)}",
    )

    expected_repo_months = frame_key_set(
        all_pairs,
        ["dataset_source", "repo_name", "month"],
    )
    actual_repo_months = frame_key_set(
        repo_month_counts,
        ["dataset_source", "repo_name", "time"],
    )
    missing_repo_months = expected_repo_months - actual_repo_months
    unexpected_repo_months = actual_repo_months - expected_repo_months
    add(
        "repo_month",
        "all_repository_months_preserved",
        not missing_repo_months and not unexpected_repo_months,
        f"missing={len(missing_repo_months)};unexpected={len(unexpected_repo_months)}",
    )
    scanned_commit_total = int(repo_month_counts["commits_scanned"].sum())
    add(
        "repo_month",
        "commits_scanned_match_eligible_pairs",
        scanned_commit_total == len(eligible_pairs),
        f"{scanned_commit_total}:{len(eligible_pairs)}",
    )
    eligible_repo_months = frame_key_set(
        eligible_pairs,
        ["dataset_source", "repo_name", "month"],
    )
    expected_zero_months = expected_repo_months - eligible_repo_months
    actual_zero_months = frame_key_set(
        repo_month_counts.loc[repo_month_counts["commits_scanned"].eq(0)],
        ["dataset_source", "repo_name", "time"],
    )
    add(
        "repo_month",
        "zero_eligible_commit_months_preserved",
        expected_zero_months == actual_zero_months,
        f"{len(actual_zero_months)}:{len(expected_zero_months)}",
    )

    input_pair_keys = frame_key_set(eligible_pairs, PAIR_KEY_COLUMNS)
    audit_pair_keys = frame_key_set(audit, AUDIT_PAIR_KEY_COLUMNS)
    missing_pair_audits = input_pair_keys - audit_pair_keys
    unexpected_pair_audits = audit_pair_keys - input_pair_keys
    add(
        "coverage",
        "missing_input_pair_audits_zero",
        not missing_pair_audits,
        len(missing_pair_audits),
    )
    add(
        "coverage",
        "unexpected_audit_pair_keys_zero",
        not unexpected_pair_audits,
        len(unexpected_pair_audits),
    )
    add(
        "coverage",
        "audited_pair_count_matches_input",
        len(audit_pair_keys) == len(input_pair_keys),
        f"{len(audit_pair_keys)}:{len(input_pair_keys)}",
    )
    duplicate_audit_files = int(audit.duplicated(AUDIT_FILE_KEY_COLUMNS).sum())
    add(
        "coverage",
        "audit_file_keys_unique",
        duplicate_audit_files == 0,
        duplicate_audit_files,
    )

    add(
        "processing",
        "extraction_errors_zero",
        len(errors) == 0,
        len(errors),
    )
    return pd.DataFrame(checks)


def build_summary(
    all_pairs: pd.DataFrame,
    eligible_pairs: pd.DataFrame,
    manifest: pd.DataFrame,
    audit: pd.DataFrame,
    errors: pd.DataFrame,
    repo_month_counts: pd.DataFrame,
    checks: pd.DataFrame,
    *,
    limited_run: bool,
) -> dict[str, Any]:
    error_stage_counts = {
        str(key): int(value)
        for key, value in errors["stage"].value_counts(dropna=False).items()
    }
    error_type_counts = {
        str(key): int(value)
        for key, value in (
            errors["error"]
            .fillna("")
            .astype(str)
            .str.split(":", n=1)
            .str[0]
            .value_counts(dropna=False)
            .items()
        )
    }
    zero_eligible_months = int(
        repo_month_counts["commits_scanned"].eq(0).sum()
    )
    return {
        "status": "PASS" if checks["passed"].eq(1).all() else "FAIL",
        "checks_total": int(len(checks)),
        "checks_passed": int(checks["passed"].eq(1).sum()),
        "checks_failed": int(checks["passed"].ne(1).sum()),
        "limited_run": bool(limited_run),
        "input_commit_pairs": int(len(all_pairs)),
        "eligible_commit_pairs_available": int(
            all_pairs["primary_scan_eligible"].eq(1).sum()
        ),
        "commit_pairs_scanned": int(len(eligible_pairs)),
        "merge_pairs_excluded": int(
            all_pairs["primary_scan_eligible"].eq(0).sum()
        ),
        "eligible_pairs_not_scanned": int(
            all_pairs["primary_scan_eligible"].eq(1).sum()
            - len(eligible_pairs)
        ),
        "repository_months": int(len(repo_month_counts)),
        "zero_eligible_commit_repository_months": zero_eligible_months,
        "python_files_audited": int(
            audit["relative_path"].astype(str).str.len().gt(0).sum()
        ),
        "function_change_events": int(len(manifest)),
        "added_function_events": int(
            manifest["change_type"].eq("added").sum()
        ),
        "modified_function_events": int(
            manifest["change_type"].eq("modified").sum()
        ),
        "module_function_events": int(
            manifest["function_kind"].isin(
                ["module_function", "module_async_function"]
            ).sum()
        ),
        "method_events": int(
            manifest["function_kind"].isin(["method", "async_method"]).sum()
        ),
        "nested_function_events": int(
            manifest["function_kind"].isin(
                ["nested_function", "nested_async_function"]
            ).sum()
        ),
        "extraction_errors": int(len(errors)),
        "error_stage_counts": error_stage_counts,
        "error_type_counts": error_type_counts,
        "source_artifact_renderer": "ast.unparse",
        "python_version": sys.version.split()[0],
        "primary_event_definition": (
            "One structurally added or modified named Python function in one "
            "commit; repeated edits and later reverts remain separate events."
        ),
        "downstream_outcomes": {
            "total_count": "function_change_events",
            "agc_velocity_like_count": "agc_function_change_events",
            "hwc_count": "hwc_function_change_events",
            "composition_ratio": "agc_function_change_event_ratio",
        },
    }

