        mode="w",
        encoding="utf-8",
        dir=path.parent,
        prefix=f".{path.name}.",
        suffix=".tmp",
        delete=False,
    ) as handle:
        temporary_path = Path(handle.name)
        json.dump(payload, handle, indent=2, sort_keys=True, default=str)
        handle.write("\n")
    os.replace(temporary_path, path)


def add_check(
    checks: list[dict[str, Any]],
    name: str,
    passed: bool,
    observed: Any,
    expected: Any,
    note: str,
) -> None:
    checks.append(
        {
            "check_name": name,
            "passed": bool(passed),
            "observed": observed,
            "expected": expected,
            "note": note,
        }
    )


def assign_pilot_band(tokens: pd.Series) -> pd.Categorical:
    labels = pd.Series(pd.NA, index=tokens.index, dtype="string")
    for lower, upper, label in PILOT_BANDS:
        labels.loc[tokens.between(lower, upper, inclusive="both")] = label
    return pd.Categorical(
        labels,
        categories=PILOT_BAND_LABELS,
        ordered=True,
    )


def derive_treatment_period(frame: pd.DataFrame) -> pd.Series:
    source = frame["dataset_source"].astype("string").str.lower()
    relative = pd.to_numeric(frame["time_to_event"], errors="coerce")
    result = pd.Series("unknown", index=frame.index, dtype="string")
    result.loc[source.eq("control")] = "control"
    treatment = source.eq("treatment")
    result.loc[treatment & relative.lt(0)] = "pre"
    result.loc[treatment & relative.eq(0)] = "event"
    result.loc[treatment & relative.gt(0)] = "post"
    result.loc[treatment & relative.isna()] = "treatment_unknown_time"
    return result


def add_share_columns(frame: pd.DataFrame, total_column: str) -> pd.DataFrame:
    result = frame.copy()
    denominator = pd.to_numeric(result[total_column], errors="coerce")
    result["agc_share_within_range"] = np.where(
        denominator.gt(0), result["agc_count"] / denominator, np.nan
    )
    result["hwc_share_within_range"] = np.where(
        denominator.gt(0), result["hwc_count"] / denominator, np.nan
    )
    return result


def build_band_summary(
    frame: pd.DataFrame,
    unit_column: str,
    total_label: str,
) -> pd.DataFrame:
    grouped = (
        frame.groupby("token_range", observed=False, dropna=False)
        .agg(
            **{
                total_label: (unit_column, "nunique"),
                "agc_count": (
                    AGC_COLUMN,
                    lambda values: int(values.groupby(frame.loc[values.index, unit_column]).max().sum()),
                ),
                "hwc_count": (
                    HWC_COLUMN,
                    lambda values: int(values.groupby(frame.loc[values.index, unit_column]).max().sum()),
                ),
                "mean_function_npr": ("function_npr", "mean"),
                "median_function_npr": ("function_npr", "median"),
            }
        )
        .reset_index()
    )
    grouped["token_range"] = grouped["token_range"].astype("string")
    grouped = add_share_columns(grouped, total_label)
    grand_total = int(grouped[total_label].sum())
    grouped["share_of_all_regular_units"] = np.where(
        grand_total > 0, grouped[total_label] / grand_total, np.nan
    )
    return grouped


def build_unique_body_band_summary(unique_bodies: pd.DataFrame) -> pd.DataFrame:
    grouped = (
        unique_bodies.groupby("token_range", observed=False, dropna=False)
        .agg(
            unique_bodies=(BODY_COLUMN, "size"),
            agc_count=(AGC_COLUMN, "sum"),
            hwc_count=(HWC_COLUMN, "sum"),
            mean_function_npr=("function_npr", "mean"),
            median_function_npr=("function_npr", "median"),
        )
        .reset_index()
    )
    grouped["token_range"] = grouped["token_range"].astype("string")
    grouped = add_share_columns(grouped, "unique_bodies")
    total = int(grouped["unique_bodies"].sum())
    grouped["share_of_all_regular_unique_bodies"] = np.where(
        total > 0, grouped["unique_bodies"] / total, np.nan
    )
    return grouped


def build_event_band_summary(events: pd.DataFrame) -> pd.DataFrame:
    grouped = (
        events.groupby("token_range", observed=False, dropna=False)
        .agg(
            event_rows=("function_event_id", "size"),
            unique_bodies=(BODY_COLUMN, "nunique"),
            agc_count=(AGC_COLUMN, "sum"),
            hwc_count=(HWC_COLUMN, "sum"),
            mean_function_npr=("function_npr", "mean"),
            median_function_npr=("function_npr", "median"),
        )
        .reset_index()
    )
    grouped["token_range"] = grouped["token_range"].astype("string")
    grouped = add_share_columns(grouped, "event_rows")
    total = int(grouped["event_rows"].sum())
    grouped["share_of_all_regular_events"] = np.where(
        total > 0, grouped["event_rows"] / total, np.nan
    )
    grouped["event_rows_per_unique_body"] = np.where(
        grouped["unique_bodies"].gt(0),
        grouped["event_rows"] / grouped["unique_bodies"],
        np.nan,
    )
    return grouped


def build_exact_token_summary(
    frame: pd.DataFrame,
    unit: str,
) -> pd.DataFrame:
    if unit == "body":
        grouped = (
            frame.groupby(TOKEN_COLUMN, dropna=False)
            .agg(
                unique_bodies=(BODY_COLUMN, "size"),
                agc_count=(AGC_COLUMN, "sum"),
                hwc_count=(HWC_COLUMN, "sum"),
                mean_function_npr=("function_npr", "mean"),
                median_function_npr=("function_npr", "median"),
            )
            .reset_index()
        )
        return add_share_columns(grouped, "unique_bodies")

    grouped = (
        frame.groupby(TOKEN_COLUMN, dropna=False)
        .agg(
            event_rows=("function_event_id", "size"),
            unique_bodies=(BODY_COLUMN, "nunique"),
            agc_count=(AGC_COLUMN, "sum"),
            hwc_count=(HWC_COLUMN, "sum"),
            mean_function_npr=("function_npr", "mean"),
            median_function_npr=("function_npr", "median"),
        )
        .reset_index()
    )
    grouped = add_share_columns(grouped, "event_rows")
    grouped["event_rows_per_unique_body"] = np.where(
        grouped["unique_bodies"].gt(0),
        grouped["event_rows"] / grouped["unique_bodies"],
        np.nan,
    )
    return grouped


def build_window_summary(unique_bodies: pd.DataFrame) -> pd.DataFrame:
    return (
        unique_bodies.groupby("n_expected_windows", dropna=False)
        .agg(
            unique_bodies=(BODY_COLUMN, "size"),
            minimum_tokens=(TOKEN_COLUMN, "min"),
            maximum_tokens=(TOKEN_COLUMN, "max"),
            agc_count=(AGC_COLUMN, "sum"),
            hwc_count=(HWC_COLUMN, "sum"),
            mean_function_npr=("function_npr", "mean"),
            median_function_npr=("function_npr", "median"),
        )
        .reset_index()
        .pipe(add_share_columns, "unique_bodies")
    )


def build_grouped_event_summary(
    events: pd.DataFrame,
    group_columns: list[str],
) -> pd.DataFrame:
    grouped = (
        events.groupby([*group_columns, "token_range"], observed=False, dropna=False)
        .agg(
            event_rows=("function_event_id", "size"),
            unique_bodies=(BODY_COLUMN, "nunique"),
            agc_count=(AGC_COLUMN, "sum"),
            hwc_count=(HWC_COLUMN, "sum"),
        )
        .reset_index()
    )
    grouped["token_range"] = grouped["token_range"].astype("string")
    return add_share_columns(grouped, "event_rows")


def build_period_totals(events: pd.DataFrame) -> pd.DataFrame:
    """Summarize event rows and distinct bodies for each adoption period."""
    group_columns = ["dataset_source", "treatment_period"]
    event_totals = (
        events.groupby(group_columns, dropna=False)
        .agg(
            event_rows=("function_event_id", "size"),
            agc_event_rows=(AGC_COLUMN, "sum"),
            hwc_event_rows=(HWC_COLUMN, "sum"),
        )
        .reset_index()
    )

    period_bodies = events.drop_duplicates([*group_columns, BODY_COLUMN])
    body_totals = (
        period_bodies.groupby(group_columns, dropna=False)
        .agg(
            unique_bodies=(BODY_COLUMN, "size"),
            agc_unique_bodies=(AGC_COLUMN, "sum"),
            hwc_unique_bodies=(HWC_COLUMN, "sum"),
        )
        .reset_index()
    )

    result = event_totals.merge(
        body_totals,
        on=group_columns,
        how="outer",
        validate="one_to_one",
    )
    result["agc_event_share"] = np.where(
        result["event_rows"].gt(0),
        result["agc_event_rows"] / result["event_rows"],
        np.nan,
    )
    result["agc_unique_body_share"] = np.where(
        result["unique_bodies"].gt(0),
        result["agc_unique_bodies"] / result["unique_bodies"],
        np.nan,
    )
    return result


def build_unique_body_band_by_period(events: pd.DataFrame) -> pd.DataFrame:
    """Count distinct bodies within each period and token band."""
    group_columns = ["dataset_source", "treatment_period", "token_range"]
    period_bodies = events.drop_duplicates(
        ["dataset_source", "treatment_period", BODY_COLUMN]
    )
    grouped = (
        period_bodies.groupby(
            group_columns,
            observed=False,
            dropna=False,
        )
        .agg(
            unique_bodies=(BODY_COLUMN, "size"),
            agc_count=(AGC_COLUMN, "sum"),
            hwc_count=(HWC_COLUMN, "sum"),
            mean_function_npr=("function_npr", "mean"),
            median_function_npr=("function_npr", "median"),
        )
        .reset_index()
    )
    grouped["token_range"] = grouped["token_range"].astype("string")
    grouped = add_share_columns(grouped, "unique_bodies")
    period_denominator = grouped.groupby(
        ["dataset_source", "treatment_period"],
        dropna=False,
    )["unique_bodies"].transform("sum")
    grouped["share_of_period_unique_bodies"] = np.where(
        period_denominator.gt(0),
        grouped["unique_bodies"] / period_denominator,
        np.nan,
    )
    return grouped


def build_treatment_event_time_totals(events: pd.DataFrame) -> pd.DataFrame:
    """Summarize treatment events at each exact relative event month."""
    treatment = events.loc[
        events["dataset_source"].astype("string").str.lower().eq("treatment")
    ].copy()
    treatment["time_to_event"] = pd.to_numeric(
        treatment["time_to_event"],
        errors="raise",
    ).astype("int64")

    event_totals = (
        treatment.groupby("time_to_event", dropna=False)
        .agg(
            event_rows=("function_event_id", "size"),
            agc_event_rows=(AGC_COLUMN, "sum"),
            hwc_event_rows=(HWC_COLUMN, "sum"),
        )
        .reset_index()
    )
    event_time_bodies = treatment.drop_duplicates(["time_to_event", BODY_COLUMN])
    body_totals = (
        event_time_bodies.groupby("time_to_event", dropna=False)
        .agg(
            unique_bodies=(BODY_COLUMN, "size"),
            agc_unique_bodies=(AGC_COLUMN, "sum"),
            hwc_unique_bodies=(HWC_COLUMN, "sum"),
        )
        .reset_index()
    )
    result = event_totals.merge(
        body_totals,
        on="time_to_event",
        how="outer",
        validate="one_to_one",
    )
    result["agc_event_share"] = np.where(
        result["event_rows"].gt(0),
        result["agc_event_rows"] / result["event_rows"],
        np.nan,
    )
    result["agc_unique_body_share"] = np.where(
        result["unique_bodies"].gt(0),
        result["agc_unique_bodies"] / result["unique_bodies"],
        np.nan,
    )
    return result.sort_values("time_to_event").reset_index(drop=True)


def build_event_band_by_event_time(events: pd.DataFrame) -> pd.DataFrame:
    """Summarize treatment event rows by exact event time and token band."""
    treatment = events.loc[
        events["dataset_source"].astype("string").str.lower().eq("treatment")
    ].copy()
    treatment["time_to_event"] = pd.to_numeric(
        treatment["time_to_event"],
        errors="raise",
    ).astype("int64")
    return build_grouped_event_summary(treatment, ["time_to_event"])



def normalize_pair_inputs(
    treatment_meta: pd.DataFrame,
    matched_pairs: pd.DataFrame,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Normalize treatment adoption metadata and the strict matched-pair file."""
    require_columns(
        treatment_meta,
        ["repo_name", "event_month"],
        "Treatment metadata",
    )
    require_columns(
        matched_pairs,
        ["treatment_repo", "control_repo"],
        "Matched treatment-control pairs",
    )

    meta = treatment_meta[["repo_name", "event_month"]].copy()
    meta["repo_name"] = meta["repo_name"].astype("string").str.strip()
    meta["event_month"] = meta["event_month"].astype("string").str.strip().str[:7]
    meta = meta.loc[meta["repo_name"].ne("") & meta["event_month"].ne("")].copy()

    parsed_event_month = pd.to_datetime(
        meta["event_month"], format="%Y-%m", errors="coerce"
    )
    invalid_meta_months = int(parsed_event_month.isna().sum())
    if invalid_meta_months:
        examples = meta.loc[parsed_event_month.isna(), "event_month"].head(20).tolist()
        raise ValidationError(
            "Treatment metadata contains invalid event_month values: "
            f"{examples}"
        )
    meta["event_month"] = parsed_event_month.dt.to_period("M").astype("string")

    conflicting_meta = (
        meta.groupby("repo_name")["event_month"].nunique(dropna=False).gt(1)
    )
    if conflicting_meta.any():
        examples = conflicting_meta.loc[conflicting_meta].index[:20].tolist()
        raise ValidationError(
            "Treatment metadata contains conflicting event months for: "
            f"{examples}"
        )
    meta = meta.drop_duplicates("repo_name").reset_index(drop=True)

    # Keep only the identifiers required for calendar alignment. The strict
    # pair manifest also contains an ``event_month`` metadata column. Retaining
    # that column would collide with the generated relative ``event_month``
    # column during the cross join and produce pandas suffixes such as
    # ``event_month_x`` and ``event_month_y``.
    pairs = matched_pairs[["treatment_repo", "control_repo"]].copy()
    pairs["treatment_repo"] = (
        pairs["treatment_repo"].astype("string").str.strip()
    )
    pairs["control_repo"] = pairs["control_repo"].astype("string").str.strip()
    pairs = pairs.loc[
        pairs["treatment_repo"].ne("") & pairs["control_repo"].ne("")
    ].copy()
    pairs = pairs.drop_duplicates(["treatment_repo", "control_repo"])
    pairs = pairs.sort_values(
        ["treatment_repo", "control_repo"], kind="stable"
    ).reset_index(drop=True)
    pairs.insert(0, "pair_id", np.arange(1, len(pairs) + 1, dtype="int64"))
    if pairs.empty:
        raise ValidationError("Matched treatment-control pair file is empty")

    return meta, pairs


def build_pair_calendar_alignment(
    treatment_meta: pd.DataFrame,
    matched_pairs: pd.DataFrame,
    minimum_event_time: int,
    maximum_event_time: int,
) -> pd.DataFrame:
    """Expand every matched pair over relative months and aligned calendar time."""
    if minimum_event_time > maximum_event_time:
        raise ValueError("minimum_event_time must not exceed maximum_event_time")

    alignment = matched_pairs.merge(
        treatment_meta.rename(
            columns={
                "repo_name": "treatment_repo",
                "event_month": "treatment_event_month",
            }
        ),
        on="treatment_repo",
        how="left",
        validate="many_to_one",
        indicator="treatment_meta_merge_status",
    )
    unresolved = alignment["treatment_meta_merge_status"].ne("both")
    if unresolved.any():
        examples = alignment.loc[unresolved, "treatment_repo"].head(20).tolist()
        raise ValidationError(
            "Matched treatments missing adoption metadata: " f"{examples}"
        )
    alignment = alignment.drop(columns="treatment_meta_merge_status")

    relative_months = pd.DataFrame(
        {
            "event_month": np.arange(
                minimum_event_time,
                maximum_event_time + 1,
                dtype="int64",
            )
        }
    )
    alignment = alignment.merge(relative_months, how="cross")
    event_periods = pd.PeriodIndex(
        alignment["treatment_event_month"], freq="M"
    )
    alignment["aligned_time"] = [
        str(period + int(offset))
        for period, offset in zip(event_periods, alignment["event_month"])
    ]
    return alignment[
        [
            "pair_id",
            "treatment_repo",
            "control_repo",
            "treatment_event_month",
            "event_month",
            "aligned_time",
        ]
    ].copy()


def build_pair_aligned_inputs(
    events: pd.DataFrame,
    panel: pd.DataFrame,
    alignment: pd.DataFrame,
    minimum_event_time: int,
    maximum_event_time: int,
) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """Create pair-aligned event rows and repository-month exposure tables.

    Treatment rows retain their real time_to_event values and are never
    multiplied by the number of matched controls. Control rows are aligned to
    the calendar month implied by each matched treatment's adoption month.
    A control event or repository-month that maps to the same relative month
    through multiple pairs is counted once for that relative month.
    """
    sources = events["dataset_source"].astype("string").str.lower()

    treatment_events = events.loc[sources.eq("treatment")].copy()
    treatment_events["event_month"] = pd.to_numeric(
        treatment_events["time_to_event"], errors="coerce"
    )
    treatment_events = treatment_events.loc[
        treatment_events["event_month"].between(
            minimum_event_time, maximum_event_time, inclusive="both"
        )
    ].copy()
    treatment_events["event_month"] = treatment_events["event_month"].astype(
        "int64"
    )
    treatment_events["alignment_pair_count"] = pd.Series(
        pd.NA, index=treatment_events.index, dtype="Int64"
    )

    control_events = events.loc[sources.eq("control")].copy()
    control_events = control_events.merge(
        alignment,
        left_on=["repo_name", "time"],
        right_on=["control_repo", "aligned_time"],
        how="inner",
        validate="many_to_many",
    )
    if not control_events.empty:
        pair_counts = (
            control_events.groupby(["event_month", "function_event_id"])["pair_id"]
            .nunique()
            .rename("alignment_pair_count")
            .reset_index()
        )
        control_events = control_events.drop_duplicates(
            ["event_month", "function_event_id"]
        ).drop(columns="alignment_pair_count", errors="ignore")
        control_events = control_events.merge(
            pair_counts,
            on=["event_month", "function_event_id"],
            how="left",
            validate="one_to_one",
        )
        control_events["alignment_pair_count"] = control_events[
            "alignment_pair_count"
        ].astype("Int64")
    control_events["dataset_source"] = "control"

    aligned_columns = list(events.columns)
    for column in ["event_month", "alignment_pair_count"]:
        if column not in aligned_columns:
            aligned_columns.append(column)
    aligned_events = pd.concat(
        [
            treatment_events.reindex(columns=aligned_columns),
            control_events.reindex(columns=aligned_columns),
        ],
        ignore_index=True,
    )

    panel_sources = panel["dataset_source"].astype("string").str.lower()
    treatment_panel = panel.loc[panel_sources.eq("treatment")].copy()
    treatment_panel["event_month"] = pd.to_numeric(
        treatment_panel["time_to_event"], errors="coerce"
    )
    treatment_panel = treatment_panel.loc[
        treatment_panel["event_month"].between(
            minimum_event_time, maximum_event_time, inclusive="both"
        )
    ].copy()
    treatment_panel["event_month"] = treatment_panel["event_month"].astype(
        "int64"
    )
    treatment_panel = treatment_panel.drop_duplicates(
        ["event_month", "repo_name", "time"]
    )
    treatment_panel["dataset_source"] = "treatment"
    treatment_panel["aligned_pair_count"] = pd.NA

    control_panel = panel.loc[panel_sources.eq("control")].copy()
    control_panel = control_panel.merge(
        alignment,
        left_on=["repo_name", "time"],
        right_on=["control_repo", "aligned_time"],
        how="inner",
        validate="many_to_many",
    )
    if not control_panel.empty:
        pair_counts = (
            control_panel.groupby(["event_month", "repo_name", "time"])["pair_id"]
            .nunique()
            .rename("aligned_pair_count")
            .reset_index()
        )
        control_panel = control_panel.drop_duplicates(
            ["event_month", "repo_name", "time"]
        ).drop(columns="aligned_pair_count", errors="ignore")
        control_panel = control_panel.merge(
            pair_counts,
            on=["event_month", "repo_name", "time"],
            how="left",
            validate="one_to_one",
        )
    control_panel["dataset_source"] = "control"

    exposure_rows: list[dict[str, Any]] = []
    for event_month in range(minimum_event_time, maximum_event_time + 1):
        for source, source_panel in [
            ("treatment", treatment_panel),
            ("control", control_panel),
        ]:
            subset = source_panel.loc[source_panel["event_month"].eq(event_month)]
            exposure_rows.append(
                {
                    "event_month": event_month,
                    "dataset_source": source,
                    "panel_repo_months": int(
                        subset[["repo_name", "time"]].drop_duplicates().shape[0]
                    ),
                    "panel_repositories": int(subset["repo_name"].nunique()),
                    "aligned_pairs": int(
                        alignment.loc[
                            alignment["event_month"].eq(event_month), "pair_id"
                        ].nunique()
                    ),
                }
            )
    exposure = pd.DataFrame(exposure_rows)

    audit_rows: list[dict[str, Any]] = []
    for event_month in range(minimum_event_time, maximum_event_time + 1):
        row: dict[str, Any] = {"event_month": event_month}
        for source in ["treatment", "control"]:
            event_subset = aligned_events.loc[
                aligned_events["dataset_source"].eq(source)
                & aligned_events["event_month"].eq(event_month)
            ]
            exposure_subset = exposure.loc[
                exposure["dataset_source"].eq(source)
                & exposure["event_month"].eq(event_month)
            ].iloc[0]
            row[f"{source}_event_rows"] = int(len(event_subset))
            row[f"{source}_unique_bodies"] = int(
                event_subset[BODY_COLUMN].nunique()
            )
            row[f"{source}_panel_repo_months"] = int(
                exposure_subset["panel_repo_months"]
            )
            row[f"{source}_panel_repositories"] = int(
                exposure_subset["panel_repositories"]
            )
        row["aligned_pairs"] = int(
            alignment.loc[
                alignment["event_month"].eq(event_month), "pair_id"
            ].nunique()
        )
        audit_rows.append(row)

    return aligned_events, exposure, pd.DataFrame(audit_rows)


def build_monthly_treatment_control_distribution(
    aligned_events: pd.DataFrame,
    exposure: pd.DataFrame,
    minimum_event_time: int,
    maximum_event_time: int,
    unit: str,
) -> pd.DataFrame:
    """Compare treatment and matched controls at aligned relative months."""
    if unit not in {"body", "event"}:
        raise ValueError(f"Unsupported unit: {unit}")
    unit_label = "unique_body" if unit == "body" else "event_row"
    if minimum_event_time > maximum_event_time:
        raise ValueError("minimum_event_time must not exceed maximum_event_time")

    sources = ["treatment", "control"]
    event_months = list(range(minimum_event_time, maximum_event_time + 1))
    classifications = ["ALL", "AGC-like", "HWC-like"]
    token_ranges = ["ALL", *PILOT_BAND_LABELS]

    scoped_events = aligned_events.copy()
    scoped_events["event_month"] = pd.to_numeric(
        scoped_events["event_month"], errors="raise"
    ).astype("int64")
    exposure_lookup = {
        (int(row.event_month), str(row.dataset_source)): {
            "panel_repo_months": int(row.panel_repo_months),
            "panel_repositories": int(row.panel_repositories),
            "aligned_pairs": int(row.aligned_pairs),
        }
        for row in exposure.itertuples(index=False)
    }

    rows: list[dict[str, Any]] = []
    for event_month in event_months:
        month_events = scoped_events.loc[
            scoped_events["event_month"].eq(event_month)
        ]
        for classification in classifications:
            if classification == "ALL":
                class_mask = pd.Series(True, index=month_events.index)
            elif classification == "AGC-like":
                class_mask = month_events[AGC_COLUMN].eq(1)
            else:
                class_mask = month_events[HWC_COLUMN].eq(1)

            for token_range in token_ranges:
                if token_range == "ALL":
                    band_mask = pd.Series(True, index=month_events.index)
                else:
                    band_mask = month_events["token_range"].astype("string").eq(
                        token_range
                    )

                row: dict[str, Any] = {
                    "classification": classification,
                    "token_range": token_range,
                    "event_month": event_month,
                }
                for source in sources:
                    source_subset = month_events.loc[
                        month_events["dataset_source"].eq(source)
                        & class_mask
                        & band_mask
                    ]
                    exposure_values = exposure_lookup.get(
                        (event_month, source),
                        {
                            "panel_repo_months": 0,
                            "panel_repositories": 0,
                            "aligned_pairs": 0,
                        },
                    )
                    repo_months = int(exposure_values["panel_repo_months"])
                    repositories = int(exposure_values["panel_repositories"])

                    if unit == "body":
                        count = int(source_subset[BODY_COLUMN].nunique())
                    else:
                        count = int(len(source_subset))

                    row[f"{source}_{unit_label}_count"] = count
                    row[f"{source}_panel_repo_months"] = repo_months
                    row[f"{source}_panel_repositories"] = repositories
                    row[f"{source}_aligned_pairs"] = int(
                        exposure_values["aligned_pairs"]
                    )
                    row[f"{source}_{unit_label}_count_per_100_repo_months"] = (
                        100.0 * count / repo_months if repo_months > 0 else np.nan
                    )
                    row[f"{source}_{unit_label}_count_per_100_repositories"] = (
                        100.0 * count / repositories
                        if repositories > 0
                        else np.nan
                    )

                row[f"{unit_label}_count_difference_treatment_minus_control"] = (
                    row[f"treatment_{unit_label}_count"]
                    - row[f"control_{unit_label}_count"]
                )
                rows.append(row)

    result = pd.DataFrame(rows)
    for source in sources:
        count_column = f"{source}_{unit_label}_count"
        denominator = (
            result.loc[result["token_range"].eq("ALL")]
            .set_index(["classification", "event_month"])[count_column]
        )
        keys = pd.MultiIndex.from_frame(
            result[["classification", "event_month"]]
        )
        mapped = denominator.reindex(keys).to_numpy()
        numerator = result[count_column].to_numpy(dtype="float64")
        share = np.full(len(result), np.nan, dtype="float64")
        np.divide(numerator, mapped, out=share, where=mapped > 0)
        result[f"{source}_{unit_label}_share_within_month"] = share

    classification_order = {"ALL": 0, "AGC-like": 1, "HWC-like": 2}
    token_range_order = {
        label: index for index, label in enumerate(["ALL", *PILOT_BAND_LABELS])
    }
    result["_classification_order"] = result["classification"].map(
        classification_order
    )
    result["_token_range_order"] = result["token_range"].map(token_range_order)
    result = result.sort_values(
        ["event_month", "_classification_order", "_token_range_order"],
        kind="stable",
    ).drop(columns=["_classification_order", "_token_range_order"])
    return result.reset_index(drop=True)


def validate_monthly_alignment(
    monthly: pd.DataFrame,
    unit: str,
    post_month_start: int,
    post_month_end: int,
    checks: list[dict[str, Any]],
) -> None:
    """Add semantic checks that prevent silent zero-control outputs."""
    unit_label = "unique_body" if unit == "body" else "event_row"
    all_rows = monthly.loc[
        monthly["classification"].eq("ALL")
        & monthly["token_range"].eq("ALL")
    ].copy()

    zero_control_exposures = int(all_rows["control_panel_repo_months"].eq(0).sum())
    add_check(
        checks,
        f"{unit_label}_control_exposure_nonzero_each_event_month",
        zero_control_exposures == 0,
        zero_control_exposures,
        0,
        "Every aligned event month must contain matched control repository-month exposure.",
    )

    focused = all_rows.loc[
        all_rows["event_month"].between(
            post_month_start, post_month_end, inclusive="both"
        )
    ]
    control_total = int(focused[f"control_{unit_label}_count"].sum())
    add_check(
        checks,
        f"{unit_label}_control_post_month_counts_not_all_zero",
        control_total > 0,
        control_total,
        "> 0",
        "Matched control observations must not collapse to all zero after calendar alignment.",
    )

    band_rows = monthly.loc[
        monthly["token_range"].ne("ALL")
        & monthly["classification"].isin(["AGC-like", "HWC-like"])
    ]
    band_sums = (
        band_rows.groupby(["event_month", "classification"], dropna=False)[
            [
                f"treatment_{unit_label}_count",
                f"control_{unit_label}_count",
            ]
        ]
        .sum()
        .reset_index()
    )
    class_all = monthly.loc[
        monthly["token_range"].eq("ALL")
        & monthly["classification"].isin(["AGC-like", "HWC-like"]),
        [
            "event_month",
            "classification",
            f"treatment_{unit_label}_count",
            f"control_{unit_label}_count",
        ],
    ]
    reconstructed = class_all.merge(
        band_sums,
        on=["event_month", "classification"],
        suffixes=("_all", "_bands"),
        validate="one_to_one",
    )
    for source in ["treatment", "control"]:
        mismatch = int(
            reconstructed[
                f"{source}_{unit_label}_count_all"
            ].ne(reconstructed[f"{source}_{unit_label}_count_bands"]).sum()
        )
        add_check(
            checks,
            f"{unit_label}_{source}_token_bands_reconstruct_classification_totals",
            mismatch == 0,
            mismatch,
            0,
            "Ten token bands must reconstruct each AGC/HWC monthly total.",
        )

    all_classification = monthly.loc[
        monthly["classification"].eq("ALL")
        & monthly["token_range"].eq("ALL")
    ]
    agc_hwc = (
        monthly.loc[
            monthly["classification"].isin(["AGC-like", "HWC-like"])
            & monthly["token_range"].eq("ALL")
        ]
        .groupby("event_month")
        .agg(
            treatment_sum=(f"treatment_{unit_label}_count", "sum"),
            control_sum=(f"control_{unit_label}_count", "sum"),
        )
        .reset_index()
    )
    partition = all_classification.merge(
        agc_hwc, on="event_month", validate="one_to_one"
    )
    for source in ["treatment", "control"]:
        mismatch = int(
            partition[f"{source}_{unit_label}_count"].ne(
                partition[f"{source}_sum"]
            ).sum()
        )
        add_check(
            checks,
            f"{unit_label}_{source}_agc_hwc_partition_monthly_all",
            mismatch == 0,
            mismatch,
            0,
            "Monthly AGC-like plus HWC-like counts must reconstruct ALL.",
        )

def build_requested_post_month_layout(
    monthly_distribution: pd.DataFrame,
    unit: str,
    post_month_start: int,
    post_month_end: int,
) -> pd.DataFrame:
    """Return the compact Month 1 through Month 6 treatment-control layout."""
    if post_month_start > post_month_end:
        raise ValueError("post_month_start must not exceed post_month_end")
    unit_label = "unique_body" if unit == "body" else "event_row"

    focused = monthly_distribution.loc[
        monthly_distribution["event_month"].between(
            post_month_start, post_month_end, inclusive="both"
        )
    ].copy()
    focused = focused.loc[
        focused["classification"].isin(["AGC-like", "HWC-like"])
    ].copy()
    focused = focused.rename(
        columns={"event_month": "month_after_adoption"}
    )
    selected_columns = [
        "classification",
        "token_range",
        "month_after_adoption",
        f"treatment_{unit_label}_count",
        f"control_{unit_label}_count",
        f"treatment_{unit_label}_count_per_100_repo_months",
        f"control_{unit_label}_count_per_100_repo_months",
        f"{unit_label}_count_difference_treatment_minus_control",
        f"treatment_{unit_label}_share_within_month",
        f"control_{unit_label}_share_within_month",
        "treatment_panel_repo_months",
        "control_panel_repo_months",
    ]
    focused = focused[selected_columns].copy()
    classification_order = {"AGC-like": 0, "HWC-like": 1}
    token_range_order = {
        label: index for index, label in enumerate(["ALL", *PILOT_BAND_LABELS])
    }
    focused["_classification_order"] = focused["classification"].map(
        classification_order
    )
    focused["_token_range_order"] = focused["token_range"].map(token_range_order)
    focused = focused.sort_values(
        ["month_after_adoption", "_classification_order", "_token_range_order"],
        kind="stable",
    ).drop(columns=["_classification_order", "_token_range_order"])
    return focused.reset_index(drop=True)

def build_pre_post_overlap(events: pd.DataFrame) -> pd.DataFrame:
    """Measure body overlap between pre-adoption and adoption-and-after."""
    treatment = events.loc[
        events["dataset_source"].astype("string").str.lower().eq("treatment")
    ].copy()
    treatment["time_to_event"] = pd.to_numeric(
        treatment["time_to_event"],
        errors="raise",
    )

    rows: list[dict[str, Any]] = []
    classifications = {
        "ALL": pd.Series(True, index=treatment.index),
        "AGC-like": treatment[AGC_COLUMN].eq(1),
        "HWC-like": treatment[HWC_COLUMN].eq(1),
    }
    band_values = ["ALL", *PILOT_BAND_LABELS]

    for classification, class_mask in classifications.items():
        for token_range in band_values:
            if token_range == "ALL":
                band_mask = pd.Series(True, index=treatment.index)
            else:
                band_mask = treatment["token_range"].astype("string").eq(token_range)

            subset = treatment.loc[class_mask & band_mask]
            pre = set(
                subset.loc[subset["time_to_event"].lt(0), BODY_COLUMN].dropna()
            )
            event = set(
                subset.loc[subset["time_to_event"].eq(0), BODY_COLUMN].dropna()
            )
            post = set(
                subset.loc[subset["time_to_event"].gt(0), BODY_COLUMN].dropna()
            )
            adoption_after = event | post

            rows.append(
                {
                    "classification": classification,
                    "token_range": token_range,
                    "pre_unique_bodies": len(pre),
                    "adoption_month_unique_bodies": len(event),
                    "strict_post_unique_bodies": len(post),
                    "adoption_and_after_unique_bodies": len(adoption_after),
                    "pre_only": len(pre - adoption_after),
                    "adoption_and_after_only": len(adoption_after - pre),
                    "observed_in_both": len(pre & adoption_after),
                    "union": len(pre | adoption_after),
                }
            )

    return pd.DataFrame(rows)


def run(args: argparse.Namespace) -> dict[str, Any]:
    require_file(args.event_classifications, "Event classifications")
    require_file(args.body_classifications, "Body classifications")
    require_file(args.panel, "Matched panel")
    require_file(args.treatment_meta, "Treatment metadata")
    require_file(args.matched_pairs, "Matched treatment-control pairs")

    if args.minimum_body_tokens != 100 or args.maximum_body_tokens != 200:
        raise ValueError(
            "This v4 diagnostic uses the frozen 100-200 pilot bands. "
            "Use minimum=100 and maximum=200."
        )

    prepare_output_directory(args.output_dir, args.overwrite_output)
    qc_dir = args.output_dir / "qc"
    qc_dir.mkdir(parents=True, exist_ok=True)

    events = normalize_keys(
        pd.read_csv(args.event_classifications, low_memory=False)
    )
    bodies = pd.read_csv(args.body_classifications, low_memory=False)
    panel = normalize_keys(pd.read_csv(args.panel, low_memory=False))
    treatment_meta_raw = pd.read_csv(args.treatment_meta, low_memory=False)
    matched_pairs_raw = pd.read_csv(args.matched_pairs, low_memory=False)
    treatment_meta, matched_pairs = normalize_pair_inputs(
        treatment_meta_raw,
        matched_pairs_raw,
    )

    require_columns(
        events,
        [
            *KEY_COLUMNS,
            "function_event_id",
            BODY_COLUMN,
            TOKEN_COLUMN,
            FUNCTION_KIND_COLUMN,
            AGC_COLUMN,
            HWC_COLUMN,
            "function_npr",
        ],
        "Event classifications",
    )
    require_columns(
        bodies,
        [
            BODY_COLUMN,
            TOKEN_COLUMN,
            "agc_like",
            "hwc_like",
            "function_npr",
            "n_expected_windows",
        ],
        "Body classifications",
    )
    require_columns(panel, [*KEY_COLUMNS, "time_to_event"], "Matched panel")

    checks: list[dict[str, Any]] = []

    events[BODY_COLUMN] = normalize_sha(events[BODY_COLUMN])
    bodies[BODY_COLUMN] = normalize_sha(bodies[BODY_COLUMN])
    events[FUNCTION_KIND_COLUMN] = (
        events[FUNCTION_KIND_COLUMN].astype("string").str.strip().str.lower()
    )

    events[AGC_COLUMN] = normalize_binary(events[AGC_COLUMN], AGC_COLUMN)
    events[HWC_COLUMN] = normalize_binary(events[HWC_COLUMN], HWC_COLUMN)
    bodies["agc_like"] = normalize_binary(bodies["agc_like"], "agc_like")
    bodies["hwc_like"] = normalize_binary(bodies["hwc_like"], "hwc_like")

    for frame, label in [(events, "events"), (bodies, "bodies")]:
        frame[TOKEN_COLUMN] = pd.to_numeric(
            frame[TOKEN_COLUMN], errors="raise"
        ).astype("int64")
        frame["function_npr"] = pd.to_numeric(
            frame["function_npr"], errors="raise"
        )
        out_of_range = int(
            (~frame[TOKEN_COLUMN].between(100, 200, inclusive="both")).sum()
        )
        add_check(
            checks,
            f"{label}_within_range100_200",
            out_of_range == 0,
            out_of_range,
            0,
            "Every analyzed row must remain inside the frozen range100_200 specification.",
        )

    body_duplicates = int(bodies.duplicated(BODY_COLUMN).sum())
    add_check(
        checks,
        "body_classifications_unique_by_sha",
        body_duplicates == 0,
        body_duplicates,
        0,
        "Body classifications must contain one row per SHA-256 body.",
    )
    if body_duplicates:
        raise ValidationError("Body classifications contain duplicate SHA values")

    body_lookup = bodies[
        [
            BODY_COLUMN,
            TOKEN_COLUMN,
            "agc_like",
            "hwc_like",
            "function_npr",
            "n_expected_windows",
        ]
    ].rename(
        columns={
            TOKEN_COLUMN: f"{TOKEN_COLUMN}_body",
            "agc_like": "agc_like_body",
            "hwc_like": "hwc_like_body",
            "function_npr": "function_npr_body",
        }
    )

    regular_events = events.loc[
        events[FUNCTION_KIND_COLUMN].eq(args.function_kind)
    ].copy()
    regular_events = regular_events.merge(
        body_lookup,
        on=BODY_COLUMN,
        how="left",
        validate="many_to_one",
        indicator="body_merge_status",
    )

    unresolved = int(regular_events["body_merge_status"].ne("both").sum())
    add_check(
        checks,
        "all_regular_events_map_to_body_classifications",
        unresolved == 0,
        unresolved,
        0,
        "Every regular-function event must map to one frozen body classification.",
    )
    if unresolved:
        raise ValidationError("Some regular-function events do not map to body rows")

    token_mismatch = int(
        regular_events[TOKEN_COLUMN]
        .ne(regular_events[f"{TOKEN_COLUMN}_body"])
        .sum()
    )
    agc_mismatch = int(
        regular_events[AGC_COLUMN].ne(regular_events["agc_like_body"]).sum()
    )
    hwc_mismatch = int(
        regular_events[HWC_COLUMN].ne(regular_events["hwc_like_body"]).sum()
    )
    npr_mismatch = int(
        (~np.isclose(
            regular_events["function_npr"],
            regular_events["function_npr_body"],
            rtol=0.0,
            atol=1e-12,
        )).sum()
    )
    add_check(
        checks,
        "regular_event_body_token_counts_match",
        token_mismatch == 0,
        token_mismatch,
        0,
        "Event and body token counts must agree.",
    )
    add_check(
        checks,
        "regular_event_body_agc_labels_match",
        agc_mismatch == 0,
        agc_mismatch,
        0,
        "Event and body AGC labels must agree.",
    )
    add_check(
        checks,
        "regular_event_body_hwc_labels_match",
        hwc_mismatch == 0,
        hwc_mismatch,
        0,
        "Event and body HWC labels must agree.",
    )
    add_check(
        checks,
        "regular_event_body_npr_scores_match",
        npr_mismatch == 0,
        npr_mismatch,
        0,
        "Event and body NPR scores must agree.",
    )

    regular_events = regular_events.drop(
        columns=[
            "body_merge_status",
            f"{TOKEN_COLUMN}_body",
            "agc_like_body",
            "hwc_like_body",
            "function_npr_body",
        ]
    )
    regular_events["token_range"] = assign_pilot_band(
        regular_events[TOKEN_COLUMN]
    )

    missing_band_events = int(pd.isna(regular_events["token_range"]).sum())
    add_check(
        checks,
        "all_regular_events_assigned_to_token_band",
        missing_band_events == 0,
        missing_band_events,
        0,
        "Every regular event must map to one frozen pilot token band.",
    )

    regular_hashes = regular_events[BODY_COLUMN].dropna().drop_duplicates()
    unique_bodies = bodies.loc[bodies[BODY_COLUMN].isin(regular_hashes)].copy()
    unique_bodies = unique_bodies.rename(
        columns={"agc_like": AGC_COLUMN, "hwc_like": HWC_COLUMN}
    )
    unique_bodies["token_range"] = assign_pilot_band(unique_bodies[TOKEN_COLUMN])

    body_partition_failures = int(
        (unique_bodies[AGC_COLUMN] + unique_bodies[HWC_COLUMN]).ne(1).sum()
    )
    event_partition_failures = int(
        (regular_events[AGC_COLUMN] + regular_events[HWC_COLUMN]).ne(1).sum()
    )
    add_check(
        checks,
        "regular_unique_body_agc_hwc_partition",
        body_partition_failures == 0,
        body_partition_failures,
        0,
        "Each regular unique body must be exactly AGC-like or HWC-like.",
    )
    add_check(
        checks,
        "regular_event_agc_hwc_partition",
        event_partition_failures == 0,
        event_partition_failures,
        0,
        "Each regular event must be exactly AGC-like or HWC-like.",
    )

    observed_event_rows = int(len(regular_events))
    observed_unique_bodies = int(len(unique_bodies))
    observed_agc_unique = int(unique_bodies[AGC_COLUMN].sum())
    observed_hwc_unique = int(unique_bodies[HWC_COLUMN].sum())

    for name, observed, expected in [
        ("regular_event_rows_match_expected", observed_event_rows, args.expected_event_rows),
        (
            "regular_unique_bodies_match_expected",
            observed_unique_bodies,
            args.expected_unique_bodies,
        ),
        (
            "regular_agc_unique_bodies_match_expected",
            observed_agc_unique,
            args.expected_agc_unique_bodies,
        ),
        (
            "regular_hwc_unique_bodies_match_expected",
            observed_hwc_unique,
            args.expected_hwc_unique_bodies,
        ),
    ]:
        add_check(
            checks,
            name,
            observed == expected,
            observed,
            expected,
            "Observed values must reproduce the prior xrun1 diagnostic.",
        )

    unique_band = build_unique_body_band_summary(unique_bodies)
    event_band = build_event_band_summary(regular_events)
    unique_exact = build_exact_token_summary(unique_bodies, unit="body")
    event_exact = build_exact_token_summary(regular_events, unit="event")
    window_summary = build_window_summary(unique_bodies)
    event_by_source = build_grouped_event_summary(
        regular_events, ["dataset_source"]
    )

    panel_duplicates = int(panel.duplicated(KEY_COLUMNS).sum())
    add_check(
        checks,
        "matched_panel_unique_by_repo_month",
        panel_duplicates == 0,
        panel_duplicates,
        0,
        "Matched panel must have one row per repository-month.",
    )
    if panel_duplicates:
        raise ValidationError("Matched panel contains duplicate repository-month keys")

    timed_events = regular_events.drop(columns=["time_to_event"], errors="ignore").merge(
        panel[[*KEY_COLUMNS, "time_to_event"]],
        on=KEY_COLUMNS,
        how="left",
        validate="many_to_one",
        indicator="panel_merge_status",
    )
    unresolved_panel = int(timed_events["panel_merge_status"].ne("both").sum())
    add_check(
        checks,
        "all_regular_events_map_to_matched_panel",
        unresolved_panel == 0,
        unresolved_panel,
        0,
        "Every regular event must map to the matched repository-month panel.",
    )
    timed_events = timed_events.drop(columns="panel_merge_status")
    timed_events["treatment_period"] = derive_treatment_period(timed_events)

    unresolved_treatment_time = int(
        timed_events["treatment_period"].eq("treatment_unknown_time").sum()
    )
    add_check(
        checks,
        "all_treatment_events_have_event_time",
        unresolved_treatment_time == 0,
        unresolved_treatment_time,
        0,
        "Every treatment regular-function event must have a relative event month.",
    )

    event_by_period = build_grouped_event_summary(
        timed_events, ["dataset_source", "treatment_period"]
    )
    period_totals = build_period_totals(timed_events)
    unique_body_by_period = build_unique_body_band_by_period(timed_events)
    event_time_totals = build_treatment_event_time_totals(timed_events)
    event_band_by_event_time = build_event_band_by_event_time(timed_events)
    pre_post_overlap = build_pre_post_overlap(timed_events)
    pair_alignment = build_pair_calendar_alignment(
        treatment_meta,
        matched_pairs,
        args.minimum_event_time,
        args.maximum_event_time,
    )
    aligned_events, aligned_exposure, alignment_audit = build_pair_aligned_inputs(
        timed_events,
        panel,
        pair_alignment,
        args.minimum_event_time,
        args.maximum_event_time,
    )
    monthly_unique_body_tc = build_monthly_treatment_control_distribution(
        aligned_events,
        aligned_exposure,
        args.minimum_event_time,
        args.maximum_event_time,
        unit="body",
    )
    monthly_event_tc = build_monthly_treatment_control_distribution(
        aligned_events,
        aligned_exposure,
        args.minimum_event_time,
        args.maximum_event_time,
        unit="event",
    )
    validate_monthly_alignment(
        monthly_unique_body_tc,
        unit="body",
        post_month_start=args.post_month_start,
        post_month_end=args.post_month_end,
        checks=checks,
    )
    validate_monthly_alignment(
        monthly_event_tc,
        unit="event",
        post_month_start=args.post_month_start,
        post_month_end=args.post_month_end,
        checks=checks,
    )
    post_month_unique_body_tc = build_requested_post_month_layout(
        monthly_unique_body_tc,
        unit="body",
        post_month_start=args.post_month_start,
        post_month_end=args.post_month_end,
    )
    post_month_event_tc = build_requested_post_month_layout(
        monthly_event_tc,
        unit="event",
        post_month_start=args.post_month_start,
